// Enhanced application with improved error handling and security
const express = require('express');
const helmet = require('helmet'); // Security headers
const rateLimit = require('express-rate-limit'); // Rate limiting
const cors = require('cors'); // CORS support
const expressSanitizer = require('express-sanitizer'); // Input sanitization
const winston = require('winston'); // Structured logging

// Initialize express app
const app = express();

// ============ Security Middleware ============
// 1. Set security headers using Helmet
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:", "https:"],
        },
    },
    hsts: {
        maxAge: 31536000, // 1 year
        includeSubDomains: true,
        preload: true
    }
}));

// 2. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// 3. Enable CORS with specific configuration
app.use(cors({
    origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true,
}));

// 4. Request size limits
app.use(express.json({ limit: '10kb' })); // Limit JSON payloads
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Limit URL-encoded payloads

// 5. Input sanitization (should be added after body parsers)
// Note: express-sanitizer middleware would need to be installed

// ============ Logger Configuration ============
const logger = winston.createLogger({
    level: process.env.LOG_LEVEL || 'info',
    format: winston.format.combine(
        winston.format.timestamp(),
        winston.format.errors({ stack: true }),
        winston.format.json()
    ),
    transports: [
        new winston.transports.Console(),
        new winston.transports.File({ filename: 'error.log', level: 'error' }),
        new winston.transports.File({ filename: 'combined.log' })
    ]
});

// ============ Custom Middleware ============
// Request logging middleware
app.use((req, res, next) => {
    const start = Date.now();

    res.on('finish', () => {
        const duration = Date.now() - start;
        logger.info({
            method: req.method,
            url: req.url,
            status: res.statusCode,
            duration: `${duration}ms`,
            ip: req.ip,
            userAgent: req.get('user-agent')
        });
    });

    next();
});

// Error handling middleware
const errorHandler = (err, req, res, next) => {
    logger.error({
        message: err.message,
        stack: err.stack,
        url: req.url,
        method: req.method,
        ip: req.ip
    });

    const statusCode = err.statusCode || 500;
    const message = process.env.NODE_ENV === 'production' 
        ? 'An unexpected error occurred' 
        : err.message;

    res.status(statusCode).json({
        error: {
            message: message,
            ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
        }
    });
};

// ============ Route Handlers with Validation ============

// Health endpoint with improved validation
app.get('/health', (req, res) => {
    try {
        // Add query parameter validation
        const { detailed } = req.query;

        // Validate query parameters
        if (detailed !== undefined && detailed !== 'true' && detailed !== 'false') {
            const error = new Error('Invalid query parameter. "detailed" must be "true" or "false"');
            error.statusCode = 400;
            throw error;
        }

        const healthData = {
            status: 'ok',
            timestamp: new Date().toISOString(),
            uptime: process.uptime(),
            memory: process.memoryUsage(),
        };

        // Add detailed info only if requested
        if (detailed === 'true') {
            healthData.systemInfo = {
                nodeVersion: process.version,
                platform: process.platform,
                arch: process.arch
            };
        }

        res.json(healthData);
    } catch (error) {
        next(error);
    }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
    try {
        const { limit, offset, sort } = req.query;

        // Validate and sanitize input
        const validatedLimit = limit ? parseInt(limit, 10) : 10;
        const validatedOffset = offset ? parseInt(offset, 10) : 0;

        // Input validation
        if (isNaN(validatedLimit) || validatedLimit < 1 || validatedLimit > 100) {
            const error = new Error('Invalid limit parameter. Must be between 1 and 100');
            error.statusCode = 400;
            throw error;
        }

        if (isNaN(validatedOffset) || validatedOffset < 0) {
            const error = new Error('Invalid offset parameter. Must be a positive integer');
            error.statusCode = 400;
            throw error;
        }

        // Validate sort parameter (whitelist approach)
        const allowedSortFields = ['name', 'id', 'email'];
        if (sort && !allowedSortFields.includes(sort)) {
            const error = new Error(`Invalid sort field. Allowed fields: ${allowedSortFields.join(', ')}`);
            error.statusCode = 400;
            throw error;
        }

        // Mock data with input validation applied
        const users = [
            { id: 1, name: 'Alice', email: 'alice@example.com' },
            { id: 2, name: 'Bob', email: 'bob@example.com' },
            { id: 3, name: 'Charlie', email: 'charlie@example.com' },
            { id: 4, name: 'Diana', email: 'diana@example.com' },
        ];

        // Apply sorting if requested
        let sortedUsers = [...users];
        if (sort) {
            sortedUsers.sort((a, b) => a[sort].localeCompare(b[sort]));
        }

        // Apply pagination
        const paginatedUsers = sortedUsers.slice(validatedOffset, validatedOffset + validatedLimit);

        // Sanitize output (remove sensitive data if needed)
        const sanitizedUsers = paginatedUsers.map(user => ({
            id: user.id,
            name: escapeHtml(user.name), // Basic XSS protection
            email: user.email // Consider masking email in production
        }));

        res.json({
            data: sanitizedUsers,
            pagination: {
                total: users.length,
                limit: validatedLimit,
                offset: validatedOffset,
                hasMore: validatedOffset + validatedLimit < users.length
            }
        });
    } catch (error) {
        next(error);
    }
});

// ============ New Route: User by ID with Validation ============
app.get('/users/:id', (req, res, next) => {
    try {
        const userId = parseInt(req.params.id, 10);

        // Validate ID parameter
        if (isNaN(userId) || userId <= 0) {
            const error = new Error('Invalid user ID. Must be a positive integer');
            error.statusCode = 400;
            throw error;
        }

        // Mock data
        const users = [
            { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
            { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
        ];

        const user = users.find(u => u.id === userId);

        if (!user) {
            const error = new Error('User not found');
            error.statusCode = 404;
            throw error;
        }

        // Return only safe fields (exclude sensitive data)
        const safeUser = {
            id: user.id,
            name: escapeHtml(user.name),
            email: user.email // In real app, might want to mask this
        };

        res.json(safeUser);
    } catch (error) {
        next(error);
    }
});

// ============ 404 Handler ============
app.use((req, res, next) => {
    const error = new Error(`Route ${req.originalUrl} not found`);
    error.statusCode = 404;
    next(error);
});

// ============ Apply Error Handler ============
app.use(errorHandler);

// ============ Utility Functions ============
function escapeHtml(text) {
    const map = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#039;'
    };
    return text.replace(/[&<>"']/g, m => map[m]);
}

// ============ Server Startup ============
const port = process.env.PORT || 3000;
const server = app.listen(port, () => {
    logger.info(`Server running on port ${port} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
    logger.info('SIGTERM received, shutting down gracefully');
    server.close(() => {
        logger.info('Server closed');
        process.exit(0);
    });
});

process.on('SIGINT', () => {
    logger.info('SIGINT received, shutting down gracefully');
    server.close(() => {
        logger.info('Server closed');
        process.exit(0);
    });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
    logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
    // In production, you might want to exit the process
    // process.exit(1);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
    logger.error('Uncaught Exception:', error);
    // In production, you might want to exit the process
    // process.exit(1);
});

module.exports = app;

// Improved application with basic error handling and security
const express = require('express');
const app = express();

// ============ Basic Security Middleware ============
// 1. Request size limits to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 2. Basic security headers
app.use((req, res, next) => {
    // Prevent XSS attacks
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('X-Frame-Options', 'DENY');
    res.setHeader('X-XSS-Protection', '1; mode=block');

    // Prevent MIME type sniffing
    res.setHeader('Content-Type', 'application/json; charset=utf-8');

    // Remove server header
    res.removeHeader('X-Powered-By');

    // CORS headers (adjust for your needs)
    res.setHeader('Access-Control-Allow-Origin', process.env.ALLOWED_ORIGIN || '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

    next();
});

// ============ Custom Middleware ============
// Request logging
const requestLogger = (req, res, next) => {
    const start = Date.now();
    console.log(`${new Date().toISOString()} - ${req.method} ${req.url} from ${req.ip}`);

    res.on('finish', () => {
        const duration = Date.now() - start;
        console.log(`${new Date().toISOString()} - ${req.method} ${req.url} ${res.statusCode} - ${duration}ms`);
    });

    next();
};
app.use(requestLogger);

// ============ Input Validation Utilities ============
const validateInteger = (value, paramName, min = 1, max = 100) => {
    const num = parseInt(value, 10);
    if (isNaN(num)) {
        throw new Error(`${paramName} must be a valid integer`);
    }
    if (num < min) {
        throw new Error(`${paramName} must be at least ${min}`);
    }
    if (num > max) {
        throw new Error(`${paramName} must be at most ${max}`);
    }
    return num;
};

const validateString = (value, paramName, allowedValues = null) => {
    if (typeof value !== 'string') {
        throw new Error(`${paramName} must be a string`);
    }
    if (allowedValues && !allowedValues.includes(value)) {
        throw new Error(`${paramName} must be one of: ${allowedValues.join(', ')}`);
    }
    return value.trim();
};

const escapeHtml = (text) => {
    if (typeof text !== 'string') return text;
    const map = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#039;'
    };
    return text.replace(/[&<>"']/g, m => map[m]);
};

// ============ Error Handling Middleware ============
const errorHandler = (err, req, res, next) => {
    console.error(`${new Date().toISOString()} - Error: ${err.message}`);
    console.error(err.stack);

    const statusCode = err.statusCode || 500;
    const message = process.env.NODE_ENV === 'production' && statusCode === 500
        ? 'An unexpected error occurred'
        : err.message;

    res.status(statusCode).json({
        error: {
            message,
            statusCode,
            timestamp: new Date().toISOString()
        }
    });
};

// ============ Route Handlers with Validation ============

// Health endpoint
app.get('/health', (req, res, next) => {
    try {
        const { detailed } = req.query;

        // Validate query parameter
        if (detailed && detailed !== 'true' && detailed !== 'false') {
            const error = new Error('Invalid detailed parameter. Must be "true" or "false"');
            error.statusCode = 400;
            throw error;
        }

        const response = {
            status: 'ok',
            timestamp: new Date().toISOString(),
            uptime: process.uptime()
        };

        if (detailed === 'true') {
            response.memoryUsage = process.memoryUsage();
            response.nodeVersion = process.version;
        }

        res.json(response);
    } catch (error) {
        next(error);
    }
});

// Users endpoint with pagination and validation
app.get('/users', (req, res, next) => {
    try {
        // Extract and validate query parameters
        const { limit = '10', offset = '0', sort } = req.query;

        const validatedLimit = validateInteger(limit, 'limit', 1, 50);
        const validatedOffset = validateInteger(offset, 'offset', 0, 1000);

        // Validate sort parameter
        let validatedSort = null;
        if (sort) {
            const allowedSortFields = ['name', 'id', 'email'];
            validatedSort = validateString(sort, 'sort', allowedSortFields);
        }

        // Mock data
        const allUsers = [
            { id: 1, name: 'Alice', email: 'alice@example.com' },
            { id: 2, name: 'Bob', email: 'bob@example.com' },
            { id: 3, name: 'Charlie', email: 'charlie@example.com' },
            { id: 4, name: 'Diana', email: 'diana@example.com' },
        ];

        // Apply sorting if specified
        let users = [...allUsers];
        if (validatedSort) {
            users.sort((a, b) => {
                const aValue = a[validatedSort];
                const bValue = b[validatedSort];
                return String(aValue).localeCompare(String(bValue));
            });
        }

        // Apply pagination
        const startIndex = validatedOffset;
        const endIndex = Math.min(startIndex + validatedLimit, users.length);
        const paginatedUsers = users.slice(startIndex, endIndex);

        // Sanitize output for XSS protection
        const safeUsers = paginatedUsers.map(user => ({
            id: user.id,
            name: escapeHtml(user.name),
            email: escapeHtml(user.email)
        }));

        res.json({
            data: safeUsers,
            meta: {
                total: allUsers.length,
                limit: validatedLimit,
                offset: validatedOffset,
                returned: safeUsers.length,
                hasMore: endIndex < allUsers.length
            }
        });

    } catch (error) {
        // Add status code if not present
        if (!error.statusCode) {
            error.statusCode = 400; // Bad Request for validation errors
        }
        next(error);
    }
});

// Get single user by ID
app.get('/users/:id', (req, res, next) => {
    try {
        const userId = validateInteger(req.params.id, 'User ID', 1, 1000);

        // Mock data
        const users = [
            { id: 1, name: 'Alice', email: 'alice@example.com' },
            { id: 2, name: 'Bob', email: 'bob@example.com' },
        ];

        const user = users.find(u => u.id === userId);

        if (!user) {
            const error = new Error('User not found');
            error.statusCode = 404;
            throw error;
        }

        // Sanitize output
        const safeUser = {
            id: user.id,
            name: escapeHtml(user.name),
            email: escapeHtml(user.email)
        };

        res.json(safeUser);

    } catch (error) {
        if (!error.statusCode) {
            error.statusCode = error.message.includes('User ID') ? 400 : 500;
        }
        next(error);
    }
});

// 404 Handler - must be after all routes
app.use((req, res, next) => {
    const error = new Error(`Route ${req.originalUrl} not found`);
    error.statusCode = 404;
    next(error);
});

// Apply error handler - must be last middleware
app.use(errorHandler);

// ============ Server Configuration ============
const port = process.env.PORT || 3000;

const server = app.listen(port, () => {
    console.log(`${new Date().toISOString()} - Server started on port ${port}`);
    console.log(`${new Date().toISOString()} - NODE_ENV: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
const shutdown = (signal) => {
    console.log(`${new Date().toISOString()} - ${signal} received, shutting down gracefully...`);

    server.close(() => {
        console.log(`${new Date().toISOString()} - Server closed`);
        process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
        console.error(`${new Date().toISOString()} - Force shutdown after timeout`);
        process.exit(1);
    }, 10000);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
    console.error(`${new Date().toISOString()} - Unhandled Rejection at:`, promise, 'reason:', reason);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
    console.error(`${new Date().toISOString()} - Uncaught Exception:`, error);
    process.exit(1);
});

module.exports = app;

