// Improved application with enhanced error handling and security
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const app = express();

// Security middleware
app.use(helmet()); // Set security headers

// CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));

// Request logging
app.use(morgan('combined'));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateRequest = (req, res, next) => {
  // Clean input data
  if (req.body) {
    for (let key in req.body) {
      if (typeof req.body[key] === 'string') {
        req.body[key] = req.body[key].trim();
      }
    }
  }

  // Check for suspicious patterns
  if (req.url.includes('..') || req.url.includes('//')) {
    return res.status(400).json({ 
      error: 'Invalid request URL',
      message: 'URL contains potentially dangerous patterns'
    });
  }

  next();
};
app.use(validateRequest);

// Custom error handling middleware
const errorHandler = (err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't expose sensitive error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({ 
      error: 'Bad Request',
      message: 'Invalid JSON payload' 
    });
  }

  // Handle specific error types
  if (err.name === 'ValidationError') {
    return res.status(400).json({ 
      error: 'Validation Error',
      message: err.message,
      details: isProduction ? undefined : err.errors
    });
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({ 
      error: 'Unauthorized',
      message: 'Authentication required' 
    });
  }

  // Generic error response
  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    message: isProduction ? 'An unexpected error occurred' : err.message,
    requestId: req.requestId || undefined
  });
};

// Request ID middleware for tracking
app.use((req, res, next) => {
  req.requestId = Math.random().toString(36).substring(2) + Date.now();
  next();
});

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    const healthStatus = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage(),
      database: 'connected' // Add actual database connection check
    };

    // Validate response data
    if (!healthStatus.timestamp || typeof healthStatus.uptime !== 'number') {
      throw new Error('Health check data validation failed');
    }

    res.json(healthStatus);
  } catch (error) {
    res.status(500).json({ 
      status: 'error',
      message: 'Health check failed',
      error: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters
    const { limit, offset } = req.query;

    // Input validation
    if (limit && (!Number.isInteger(Number(limit)) || Number(limit) < 1 || Number(limit) > 100)) {
      return res.status(400).json({
        error: 'Invalid parameter',
        message: 'Limit must be an integer between 1 and 100'
      });
    }

    if (offset && (!Number.isInteger(Number(offset)) || Number(offset) < 0)) {
      return res.status(400).json({
        error: 'Invalid parameter',
        message: 'Offset must be a non-negative integer'
      });
    }

    // Sanitize user data (never expose sensitive info)
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        createdAt: '2024-01-01T00:00:00.000Z'
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        createdAt: '2024-01-02T00:00:00.000Z'
      },
    ].map(user => ({
      id: user.id,
      name: user.name,
      email: user.email,
      // Don't expose createdAt in production unless needed
      ...(process.env.NODE_ENV === 'development' && { createdAt: user.createdAt })
    }));

    // Apply pagination if parameters provided
    const result = {
      users,
      total: users.length,
      limit: limit ? Number(limit) : users.length,
      offset: offset ? Number(offset) : 0
    };

    res.json(result);
  } catch (error) {
    next(error);
  }
});

// Add a POST endpoint with proper validation
app.post('/users', (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Input validation
    if (!name || typeof name !== 'string' || name.length < 1 || name.length > 100) {
      return res.status(400).json({
        error: 'Invalid input',
        message: 'Name must be a string between 1 and 100 characters'
      });
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email || !emailRegex.test(email)) {
      return res.status(400).json({
        error: 'Invalid input',
        message: 'Please provide a valid email address'
      });
    }

    // Prevent NoSQL injection by validating data types
    if (typeof name !== 'string' || typeof email !== 'string') {
      return res.status(400).json({
        error: 'Invalid data types',
        message: 'Name and email must be strings'
      });
    }

    // Create user (in a real app, this would save to database)
    const newUser = {
      id: 3,
      name: name.trim(), // Trim whitespace
      email: email.trim().toLowerCase(), // Normalize email
      createdAt: new Date().toISOString()
    };

    // Log creation (without sensitive data)
    console.log('User created:', { id: newUser.id, name: newUser.name });

    res.status(201).json({
      message: 'User created successfully',
      user: {
        id: newUser.id,
        name: newUser.name,
        email: newUser.email
      }
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.url}`,
    requestId: req.requestId
  });
});

// Apply error handler
app.use(errorHandler);

// Graceful shutdown handling
const server = app.listen(process.env.PORT || 3000, () => {
  console.log(`Server running on port ${process.env.PORT || 3000} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

