// Improved application with better error handling and security practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
require('dotenv').config();

const app = express();

// ======================
// Security Middleware
// ======================

// Helmet.js for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
}));

// CORS configuration (restrict to trusted origins in production)
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:3001'],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Parse JSON with size limit to prevent large payload attacks
app.use(express.json({ limit: '10kb' }));

// ======================
// Custom Middleware
// ======================

// Request logging middleware
app.use((req, res, next) => {
  const startTime = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - startTime;
    console.log(`${new Date().toISOString()} ${req.method} ${req.originalUrl} ${res.statusCode} ${duration}ms`);
  });
  next();
});

// Error handling wrapper for async routes
const asyncHandler = fn => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ======================
// Validation Functions
// ======================

// Input sanitization function
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  // Remove potentially dangerous characters
  return input.replace(/[<>]/g, '');
};

// Query parameter validation
const validateQueryParams = (params) => {
  const allowedParams = ['page', 'limit', 'sort', 'search'];
  const sanitizedParams = {};

  for (const [key, value] of Object.entries(params)) {
    if (allowedParams.includes(key)) {
      sanitizedParams[key] = sanitizeInput(value);
    }
  }

  return sanitizedParams;
};

// ======================
// Routes with Improved Error Handling
// ======================

app.get('/health', (req, res) => {
  try {
    // Validate response data
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

app.get('/users', asyncHandler(async (req, res) => {
  // Validate and sanitize query parameters
  const sanitizedParams = validateQueryParams(req.query);

  // In a real app, this would be a database query
  // Always validate and sanitize database inputs
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Additional validation: ensure no sensitive data is exposed
  const safeUsers = users.map(user => ({
    id: user.id,
    name: sanitizeInput(user.name),
    // Never expose full email addresses publicly
    email: sanitizeInput(user.email.replace(/@.*$/, '@***'))
  }));

  res.json({
    data: safeUsers,
    meta: {
      count: safeUsers.length,
      timestamp: new Date().toISOString()
    }
  });
}));

// Example of a route with parameter validation
app.get('/users/:id', asyncHandler(async (req, res) => {
  const userId = parseInt(req.params.id);

  // Validate ID parameter
  if (isNaN(userId) || userId < 1) {
    return res.status(400).json({
      error: 'Invalid user ID',
      message: 'User ID must be a positive integer'
    });
  }

  // In a real app: validate user ID format, check authorization, etc.
  // This is where you'd query the database
  res.json({
    id: userId,
    name: `User ${userId}`,
    email: `user${userId}@example.com`
  });
}));

// ======================
// Error Handling Middleware (MUST be last)
// ======================

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.originalUrl}`,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', {
    message: error.message,
    stack: process.env.NODE_ENV === 'development' ? error.stack : undefined,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't expose internal error details in production
  const response = {
    error: 'Internal Server Error',
    message: 'An unexpected error occurred',
    timestamp: new Date().toISOString()
  };

  if (process.env.NODE_ENV === 'development') {
    response.debug = error.message;
  }

  res.status(error.status || 500).json(response);
});

// ======================
// Server Configuration
// ======================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

// Graceful shutdown handling
const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on http://${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

