// Security test examples for the improved application

const request = require('supertest');
const app = require('./app_improved.js');

describe('Security Improvements Tests', () => {
  describe('Input Validation', () => {
    test('should sanitize HTML in query parameters', async () => {
      const response = await request(app)
        .get('/users?search=<script>alert("xss")</script>');

      expect(response.status).toBe(200);
      // Search parameter should be sanitized or ignored
      expect(response.body.data).toBeDefined();
    });

    test('should reject invalid user IDs', async () => {
      const response = await request(app)
        .get('/users/abc');

      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Invalid user ID');
    });

    test('should reject negative user IDs', async () => {
      const response = await request(app)
        .get('/users/-1');

      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Invalid user ID');
    });
  });

  describe('Rate Limiting', () => {
    test('should allow requests within limit', async () => {
      // First request should succeed
      const response1 = await request(app).get('/health');
      expect(response1.status).toBe(200);

      // Second request should also succeed
      const response2 = await request(app).get('/health');
      expect(response2.status).toBe(200);
    });

    // Note: Testing actual rate limit would require many requests
    // This would be done in integration tests
  });

  describe('Error Handling', () => {
    test('should return 404 for unknown routes', async () => {
      const response = await request(app)
        .get('/non-existent-route');

      expect(response.status).toBe(404);
      expect(response.body.error).toBe('Not Found');
    });

    test('should handle errors gracefully', async () => {
      // Test that the server doesn't crash on invalid input
      const response = await request(app)
        .post('/health')  // POST to a GET-only endpoint
        .send({ invalid: 'data' });

      expect(response.status).toBe(404); // Should return 404, not crash
    });
  });

  describe('Security Headers', () => {
    test('should include security headers', async () => {
      const response = await request(app).get('/health');

      // Check for important security headers
      expect(response.headers['x-content-type-options']).toBe('nosniff');
      expect(response.headers['x-frame-options']).toBe('DENY');
      expect(response.headers['x-xss-protection']).toBe('0');

      // Helmet adds these headers by default
      expect(response.headers['content-security-policy']).toBeDefined();
    });
  });

  describe('Data Sanitization', () => {
    test('should not expose sensitive user data', async () => {
      const response = await request(app).get('/users');

      expect(response.status).toBe(200);

      // Check that emails are partially masked
      response.body.data.forEach(user => {
        expect(user.email).toMatch(/@.*\*{3}$/);
      });
    });
  });
});

