// Test script to demonstrate security improvements
// Run with: node test_security.js

const http = require('http');

const BASE_URL = 'http://localhost:3000';
const TEST_REQUESTS = [
  // Valid requests
  { method: 'GET', path: '/health', description: 'Health check' },

  // Input validation tests
  { method: 'GET', path: '/users?page=-1', description: 'Negative page number' },
  { method: 'GET', path: '/users?limit=1000', description: 'Excessive limit' },
  { method: 'GET', path: '/users?sort=unsafe', description: 'Invalid sort field' },
  { method: 'GET', path: '/users?id=abc', description: 'Non-numeric ID in query' },

  // Path parameter tests
  { method: 'GET', path: '/users/abc', description: 'Non-numeric user ID' },
  { method: 'GET', path: '/users/999', description: 'Non-existent user' },

  // Malicious inputs
  { method: 'GET', path: '/users?page=<script>alert("xss")</script>', description: 'XSS attempt' },
  { method: 'GET', path: '/users/1 OR 1=1', description: 'SQL injection attempt' },

  // Rate limiting test (will need multiple requests)
  { method: 'GET', path: '/users', description: 'Normal request' },

  // Invalid routes
  { method: 'GET', path: '/admin', description: 'Non-existent route' },
  { method: 'POST', path: '/users', body: {}, description: 'Empty POST body' },
  { method: 'POST', path: '/users', body: { name: 'A'.repeat(200) }, description: 'Oversized name' },
  { method: 'POST', path: '/users', body: { name: 'Test', email: 'invalid-email' }, description: 'Invalid email format' },
];

async function makeRequest(method, path, body = null) {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: 'localhost',
      port: 3000,
      path,
      method,
      headers: {}
    };

    if (body) {
      options.headers['Content-Type'] = 'application/json';
      options.headers['Content-Length'] = Buffer.byteLength(JSON.stringify(body));
    }

    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          body: data
        });
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    if (body) {
      req.write(JSON.stringify(body));
    }

    req.end();
  });
}

async function runTests() {
  console.log('=== Security Test Suite ===\n');

  for (const test of TEST_REQUESTS) {
    try {
      console.log(`Test: ${test.description}`);
      console.log(`  ${test.method} ${test.path}`);

      const response = await makeRequest(test.method, test.path, test.body || null);

      console.log(`  Status: ${response.statusCode}`);

      // Check security headers
      console.log(`  Security Headers:`);
      const securityHeaders = [
        'x-content-type-options',
        'x-frame-options', 
        'x-xss-protection',
        'content-security-policy',
        'strict-transport-security'
      ];

      securityHeaders.forEach(header => {
        if (response.headers[header]) {
          console.log(`    ${header}: ${response.headers[header]}`);
        }
      });

      // Log error details for failed requests
      if (response.statusCode >= 400) {
        console.log(`  Validation Successful: Request properly rejected`);
        try {
          const body = JSON.parse(response.body);
          if (body.error && body.error.message) {
            console.log(`  Error Message: ${body.error.message}`);
          }
        } catch (e) {
          console.log(`  Response: ${response.body.substring(0, 100)}...`);
        }
      }

      console.log();

    } catch (error) {
      console.log(`  Error: ${error.message}\n`);
    }

    // Small delay between requests
    await new Promise(resolve => setTimeout(resolve, 100));
  }

  // Test rate limiting
  console.log('=== Rate Limiting Test (5 rapid requests) ===\n');
  for (let i = 1; i <= 5; i++) {
    try {
      const response = await makeRequest('GET', '/users');
      console.log(`Request ${i}: Status ${response.statusCode}`);
      if (response.statusCode === 429) {
        console.log(`  ✓ Rate limit triggered on request ${i}`);
      }
    } catch (error) {
      console.log(`Request ${i}: Error - ${error.message}`);
    }
  }

  console.log('\n=== Summary ===');
  console.log('Security improvements tested:');
  console.log('  ✓ Input validation');
  console.log('  ✓ Security headers');
  console.log('  ✓ Error handling');
  console.log('  ✓ Rate limiting');
  console.log('  ✓ URL parameter validation');
  console.log('\nNote: Run the enhanced server first with:');
  console.log('  npm install && npm start');
}

runTests();

