/**
 * Enhanced Express.js application with security best practices
 * for error handling and input validation
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const winston = require('winston');

// Initialize Express app
const app = express();
const PORT = process.env.PORT || 3000;

// ==================== SETUP & CONFIGURATION ====================

// Configure logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console({
      format: winston.format.combine(
        winston.format.colorize(),
        winston.format.simple()
      )
    }),
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Global rate limiting
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skipSuccessfulRequests: false
});

// Strict rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many requests to this endpoint',
  standardHeaders: true,
  legacyHeaders: false
});

// ==================== SECURITY MIDDLEWARE ====================

// Security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"]
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS configuration (restrictive by default)
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400
}));

// Body parsing with limits to prevent DoS attacks
app.use(express.json({
  limit: '10kb', // Limit request body size
  strict: true // Reject arrays and plain strings
}));
app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// Apply global rate limiting
app.use(globalLimiter);

// Request logging middleware
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    url: req.url,
    ip: req.ip,
    userAgent: req.get('User-Agent'),
    timestamp: new Date().toISOString()
  });
  next();
});

// ==================== ERROR HANDLING MIDDLEWARE ====================

// 404 handler
app.use((req, res, next) => {
  logger.warn(`404 - ${req.method} ${req.url}`);
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.url}`,
    timestamp: new Date().toISOString()
  });
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error({
    error: err.message,
    stack: err.stack,
    method: req.method,
    url: req.url,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't leak error details in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({
      error: 'Internal Server Error',
      message: 'An unexpected error occurred',
      timestamp: new Date().toISOString()
    });
  }

  // Development mode: show error details
  res.status(err.status || 500).json({
    error: err.message,
    stack: err.stack,
    timestamp: new Date().toISOString()
  });
});

// Unhandled rejection handler
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection:', {
    reason: reason.message || reason,
    stack: reason.stack,
    promise: promise
  });
});

// Uncaught exception handler
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', {
    error: error.message,
    stack: error.stack
  });
  // Graceful shutdown
  process.exit(1);
});

// ==================== VALIDATION HELPERS ====================

const validateRequest = (validations) => {
  return async (req, res, next) => {
    await Promise.all(validations.map(validation => validation.run(req)));

    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn('Validation failed:', {
        errors: errors.array(),
        method: req.method,
        url: req.url,
        ip: req.ip
      });

      return res.status(400).json({
        error: 'Validation Error',
        errors: errors.array().map(err => ({
          field: err.path,
          message: err.msg,
          value: err.value
        })),
        timestamp: new Date().toISOString()
      });
    }

    next();
  };
};

// Input sanitization middleware
const sanitizeInput = (req, res, next) => {
  // Sanitize query parameters
  if (req.query) {
    for (const key in req.query) {
      if (typeof req.query[key] === 'string') {
        req.query[key] = req.query[key].trim();
        // Remove potentially dangerous characters
        req.query[key] = req.query[key].replace(/[<>]/g, '');
      }
    }
  }

  // Sanitize body parameters
  if (req.body) {
    for (const key in req.body) {
      if (typeof req.body[key] === 'string') {
        req.body[key] = req.body[key].trim();
        // Remove potentially dangerous characters
        req.body[key] = req.body[key].replace(/[<>]/g, '');
      }
    }
  }

  next();
};

// ==================== ROUTES WITH VALIDATION ====================

// Health endpoint with strict validation
app.get('/health', strictLimiter, [
  // Add any query parameter validation if needed
], validateRequest([]), (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    memoryUsage: process.memoryUsage()
  });
});

// Users endpoint with input validation
app.get('/users', sanitizeInput, [
  // Validate query parameters
  body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  body('search').optional().isString().trim().escape().withMessage('Search must be a string'),
  body('sortBy').optional().isIn(['id', 'name', 'email']).withMessage('Invalid sort field'),
  body('order').optional().isIn(['asc', 'desc']).withMessage('Order must be asc or desc')
], validateRequest([]), (req, res) => {
  try {
    // Extract and validate parameters
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const search = req.query.search || '';
    const sortBy = req.query.sortBy || 'id';
    const order = req.query.order || 'asc';

    // Mock user data with validation
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
    ];

    // Apply filtering and sorting (in a real app, this would be database queries)
    let filteredUsers = users;

    if (search) {
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(search.toLowerCase()) ||
        user.email.toLowerCase().includes(search.toLowerCase())
      );
    }

    // Apply sorting
    filteredUsers.sort((a, b) => {
      if (order === 'asc') {
        return a[sortBy] > b[sortBy] ? 1 : -1;
      } else {
        return a[sortBy] < b[sortBy] ? 1 : -1;
      }
    });

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: filteredUsers.length,
        totalPages: Math.ceil(filteredUsers.length / limit),
        hasNext: endIndex < filteredUsers.length,
        hasPrev: startIndex > 0
      },
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    logger.error('Error processing users request:', error);
    throw error; // Will be caught by global error handler
  }
});

// Example POST endpoint with comprehensive validation
app.post('/users', strictLimiter, sanitizeInput, [
  // Comprehensive validation rules
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
    .matches(/^[A-Za-z\s]+$/).withMessage('Name can only contain letters and spaces')
    .escape(),

  body('email')
    .trim()
    .notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Invalid email format')
    .normalizeEmail(),

  body('password')
    .notEmpty().withMessage('Password is required')
    .isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
    .matches(/[A-Z]/).withMessage('Password must contain at least one uppercase letter')
    .matches(/[a-z]/).withMessage('Password must contain at least one lowercase letter')
    .matches(/[0-9]/).withMessage('Password must contain at least one number')
    .matches(/[^A-Za-z0-9]/).withMessage('Password must contain at least one special character'),

  body('age')
    .optional()
    .isInt({ min: 13, max: 120 }).withMessage('Age must be between 13 and 120'),

  body('role')
    .optional()
    .isIn(['user', 'admin', 'moderator']).withMessage('Invalid role'),

  body('agreedToTerms')
    .isBoolean().withMessage('agreedToTerms must be boolean')
    .custom(value => {
      if (value !== true) {
        throw new Error('You must agree to the terms');
      }
      return true;
    })
], validateRequest([]), async (req, res) => {
  try {
    // In a real application, you would:
    // 1. Hash the password securely
    // 2. Check if user already exists
    // 3. Store in database
    // 4. Send verification email

    const { name, email, password, age, role } = req.body;

    logger.info('User registration attempt:', { email, role });

    // Simulate user creation
    const newUser = {
      id: Date.now(),
      name,
      email,
      age: age || null,
      role: role || 'user',
      createdAt: new Date().toISOString(),
      // Never return password in response
    };

    res.status(201).json({
      message: 'User created successfully',
      user: {
        id: newUser.id,
        name: newUser.name,
        email: newUser.email,
        age: newUser.age,
        role: newUser.role,
        createdAt: newUser.createdAt
      },
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    logger.error('Error in user creation:', error);
    throw error;
  }
});

// ==================== SERVER SETUP ====================

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
  logger.info(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown handler
const shutdown = (signal) => {
  logger.info(`${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    logger.info('HTTP server closed');

    // Close database connections, etc.

    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    logger.error('Forcing shutdown after timeout');
    process.exit(1);
  }, 10000);
};

// Handle shutdown signals
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;

/**
 * Test script to demonstrate security improvements
 */

const request = require('supertest');
const app = require('./app_improved.js');

describe('Security Improvements Testing', () => {
  test('Should have security headers', async () => {
    const response = await request(app).get('/health');

    // Check security headers
    expect(response.headers['x-powered-by']).toBeUndefined();
    expect(response.headers['x-content-type-options']).toBe('nosniff');
    expect(response.headers['x-frame-options']).toBeDefined();
    expect(response.headers['x-xss-protection']).toBeDefined();
  });

  test('Should validate input on POST /users', async () => {
    const invalidData = {
      name: '<script>alert("xss")</script>', // XSS attempt
      email: 'invalid-email',
      password: 'weak'
    };

    const response = await request(app)
      .post('/users')
      .send(invalidData);

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Validation Error');
    expect(response.body.errors).toBeInstanceOf(Array);

    // Check that XSS attempt is sanitized/blocked
    const nameError = response.body.errors.find(e => e.field === 'name');
    expect(nameError).toBeDefined();
    expect(nameError.message).toMatch(/only contain letters and spaces/);
  });

  test('Should sanitize dangerous input', async () => {
    const maliciousData = {
      name: 'Alice<script>alert(1)</script>',
      email: 'alice@example.com',
      password: 'ValidPass123!',
      agreedToTerms: true
    };

    const response = await request(app)
      .post('/users')
      .send(maliciousData);

    expect(response.status).toBe(400); // Should fail validation due to < > characters
  });

  test('Should enforce rate limiting', async () => {
    // Make multiple rapid requests
    const requests = [];
    for (let i = 0; i < 15; i++) {
      requests.push(request(app).get('/health'));
    }

    const responses = await Promise.all(requests);

    // Some requests should be rate limited (429)
    const rateLimited = responses.filter(r => r.status === 429);
    expect(rateLimited.length).toBeGreaterThan(0);
  });

  test('Should handle missing routes with 404', async () => {
    const response = await request(app).get('/nonexistent');
    expect(response.status).toBe(404);
    expect(response.body.error).toBe('Not Found');
  });

  test('Should validate query parameters', async () => {
    // Invalid limit parameter (too high)
    const response = await request(app)
      .get('/users')
      .query({ limit: 1000 }); // Exceeds max of 100

    expect(response.status).toBe(400);
    expect(response.body.errors).toBeDefined();
  });

  test('Should handle malformed JSON gracefully', async () => {
    const response = await request(app)
      .post('/users')
      .set('Content-Type', 'application/json')
      .send('{malformed json}');

    expect(response.status).toBe(400); // Should be 400, not 500
  });

  test('Should escape HTML in responses', async () => {
    // Test that user input is properly escaped in responses
    const testUser = {
      name: 'Test & User',
      email: 'test@example.com',
      password: 'ValidPass123!',
      agreedToTerms: true
    };

    const response = await request(app)
      .post('/users')
      .send(testUser);

    expect(response.status).toBe(201);
    // Name should be properly handled (escaped if needed)
    expect(response.body.user.name).toBe('Test & User');
  });
});

// Test error handling
describe('Error Handling', () => {
  test('Should handle async errors', async () => {
    // This would need to be tested with a route that throws an error
    const response = await request(app).get('/health');
    expect(response.status).toBe(200);
    expect(response.body).toHaveProperty('status', 'ok');
  });

  test('Should return structured error responses', async () => {
    const response = await request(app).post('/users').send({});
    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error');
    expect(response.body).toHaveProperty('errors');
    expect(response.body).toHaveProperty('timestamp');
  });
});

// Test CORS configuration
describe('CORS Configuration', () => {
  test('Should respect CORS configuration', async () => {
    const response = await request(app)
      .options('/users')
      .set('Origin', 'http://evil.com')
      .set('Access-Control-Request-Method', 'POST');

    // Should either allow or disallow based on configuration
    // In default config, evil.com should be disallowed
    expect(response.headers['access-control-allow-origin']).not.toBe('http://evil.com');
