// Improved Express.js application with enhanced error handling and security
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const app = express();
const PORT = process.env.PORT || 3000;

// Security Middleware
app.use(helmet()); // Set security HTTP headers

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Body parsing middleware (for future POST/PUT endpoints)
app.use(express.json({ limit: '10kb' })); // Limit body size
app.use(express.urlencoded({ extended: false }));

// Add request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.url} - ${req.ip}`);
  next();
});

// Global error handler
const errorHandler = (err, req, res, next) => {
  console.error(`Error: ${err.message}`);
  console.error(`Stack: ${err.stack}`);

  // Don't expose error details in production
  const errorResponse = {
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' ? 'Something went wrong' : err.message,
    timestamp: new Date().toISOString(),
  };

  res.status(err.status || 500).json(errorResponse);
};

// Async error handler wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Health endpoint with input validation
app.get('/health', asyncHandler(async (req, res) => {
  // Validate query parameters if any
  if (Object.keys(req.query).length > 0) {
    // You could add specific validation logic here
    console.warn('Health endpoint called with query parameters:', req.query);
  }

  // Simulate some health checks
  const healthChecks = {
    database: { status: 'connected', uptime: '24h' },
    redis: { status: 'connected', uptime: '24h' },
    memory: { usage: process.memoryUsage() },
  };

  res.json({
    status: 'healthy',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    checks: healthChecks,
  });
}));

// Users endpoint with enhanced security
app.get('/users', asyncHandler(async (req, res) => {
  // Validate and sanitize input parameters
  const { page = 1, limit = 10 } = req.query;

  // Input validation
  const pageNum = parseInt(page, 10);
  const limitNum = parseInt(limit, 10);

  if (isNaN(pageNum) || pageNum < 1) {
    throw new Error('Page must be a positive integer');
  }

  if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
    throw new Error('Limit must be between 1 and 100');
  }

  // In a real application, this would come from a database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
    { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
  ];

  // Filter sensitive data before sending response
  const sanitizedUsers = users.map(user => ({
    id: user.id,
    name: user.name,
    email: user.email,
    // Don't expose role unless necessary
  }));

  // Add pagination metadata
  const response = {
    data: sanitizedUsers,
    pagination: {
      page: pageNum,
      limit: limitNum,
      total: sanitizedUsers.length,
      totalPages: Math.ceil(sanitizedUsers.length / limitNum),
    },
    timestamp: new Date().toISOString(),
  };

  res.json(response);
}));

// Add a 404 handler for undefined routes
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.url}`,
    timestamp: new Date().toISOString(),
  });
});

// Use error handler
app.use(errorHandler);

// Start server with proper error handling
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown handlers
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
    process.exit(0);
  });
});

// Handle unhandled rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to log to an external service
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // In production, you might want to restart the process
  process.exit(1);
});

module.exports = { app, server };

