    url: 'http://localhost:3000/nonexistent',
    method: 'GET',
    expected: '404 Not Found'
  },
  {
    name: 'Test 6: Check security headers',
    url: 'http://localhost:3000/health',
    method: 'HEAD',
    expected: 'Security headers present (Helmet)'
  }
];

// Function to make HTTP request
function makeRequest(testCase, callback) {
  const options = {
    hostname: 'localhost',
    port: 3000,
    path: new URL(testCase.url).pathname + new URL(testCase.url).search,
    method: testCase.method,
    headers: {
      'User-Agent': 'Security Test Script'
    }
  };

  const req = http.request(options, (res) => {
    let data = '';

    res.on('data', (chunk) => {
      data += chunk;
    });

    res.on('end', () => {
      callback(null, {
        statusCode: res.statusCode,
        headers: res.headers,
        data: testCase.method === 'HEAD' ? '' : JSON.parse(data || '{}')
      });
    });
  });

  req.on('error', (err) => {
    callback(err);
  });

  req.end();
}

