  console.log('4. ✅ 404 handling for unknown routes');
  console.log('5. ✅ Structured JSON responses');

  console.log('\nTo test rate limiting, run:');
  console.log('for i in {1..150}; do curl -s "http://localhost:3000/health" > /dev/null; echo -n "."; done');
  console.log('You should see rate limiting kick in after 100 requests.');

  // Kill server process
  serverProcess.kill();
  console.log('\nServer stopped.');
}

