# Security Configuration Guide

## Summary of Security Improvements Implemented

### 1. **Input Validation System**
```
┌─────────────────────────────────────────────┐
│           Request Flow                       │
│  ┌─────────┐  ┌────────────┐  ┌──────────┐  │
│  │ Client  │→ │ API Gateway │→ │ Input    │  │
│  │ Request │  │ (Rate Limit)│  │ Validation│  │
│  └─────────┘  └────────────┘  └──────────┘  │
│         ↓              ↓              ↓      │
│  ┌────────────┐  ┌────────────┐  ┌──────────┐│
│  │ CORS       │→ │ Sanitization│→ │ Business ││
│  │ Validation │  │ (XSS/HPP)   │  │ Logic    ││
│  └────────────┘  └────────────┘  └──────────┘│
└─────────────────────────────────────────────┘
```

### 2. **Middleware Stack Order**
```javascript
// SECURITY FIRST - Apply security middleware early
1. helmet()           // Security headers
2. cors()            // CORS restrictions
3. rateLimit()       // Rate limiting
4. compression()     // Response compression
5. json/urlencoded() // Body parsing with limits
6. xss()            // XSS protection
7. hpp()            // Parameter pollution
8. mongoSanitize()  // NoSQL injection
9. customMiddleware() // Custom validation/sanitization
10. routes()         // Application routes
11. errorHandler()   // Global error handling
```

### 3. **Security Headers Configuration**
```javascript
// Helmet Configuration Details:
helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],     // Allow from same origin only
      scriptSrc: ["'self'"],      // Allow scripts from same origin
      styleSrc: ["'self'"],       // Allow styles from same origin
      imgSrc: ["'self'", "data:"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],      // No embedded objects
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],       // No iframes
      connectSrc: ["'self'"]
    }
  },
  hidePoweredBy: true,            // Hide Express version
  hsts: {                         // Force HTTPS
    maxAge: 31536000,            // 1 year in seconds
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,                  // Prevent MIME sniffing
  xssFilter: true                // Enable XSS filter
});
```

### 4. **Rate Limiting Strategy**
```javascript
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,     // 15 minutes window
  max: 100,                     // 100 requests per window
  message: {                    // Custom error message
    status: 'error',
    message: 'Too many requests, please try again later.'
  },
  standardHeaders: true,        // Return rate limit headers
  legacyHeaders: false,         // Disable deprecated headers
  skipSuccessfulRequests: false // Count all requests
});
```

### 5. **Input Validation Rules**
```javascript
// Common Validation Patterns:
const validationRules = {
  // Numeric validation
  numbers: {
    min: 1,
    max: 100,
    integerOnly: true
  },

  // String validation
  strings: {
    maxLength: 255,
    disallowedChars: /[<>"'`$]/g,
    patterns: {
      email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
      phone: /^\+?[\d\s\-\(\)]+$/,
      username: /^[a-zA-Z0-9_-]{3,20}$/
    }
  },

  // Common security checks
  security: {
    sqlInjection: /(\b(SELECT|INSERT|UPDATE|DELETE|DROP|UNION)\b)/i,
    xssPatterns: /(<script|javascript:|on\w+\s*=)/i,
    pathTraversal: /(\.\.\/|\.\.\\|%2e%2e%2f)/i
  }
};
```

### 6. **Error Handling Strategy**
```javascript
// Production vs Development Error Responses
const getErrorResponse = (error, env) => {
  if (env === 'production') {
    return {
      status: 'error',
      message: 'An unexpected error occurred',
      errorId: generateErrorId() // For tracking without exposing details
    };
  } else {
    return {
      status: 'error',
      message: error.message,
      stack: error.stack,
      details: error.details || null
    };
  }
};

// Logging Levels
const logLevels = {
  DEBUG: process.env.NODE_ENV === 'development',
  INFO: true,
  WARN: true,
  ERROR: true,
  SECURITY: true  // Special log level for security events
};
```

### 7. **CORS Security Configuration**
```javascript
// Production CORS Settings
const productionCors = {
  origin: [
    'https://yourdomain.com',
    'https://www.yourdomain.com'
  ],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: [
    'Content-Type',
    'Authorization',
    'X-Requested-With'
  ],
  exposedHeaders: ['X-RateLimit-Limit', 'X-RateLimit-Remaining'],
  credentials: true,
  maxAge: 86400,
  preflightContinue: false,
  optionsSuccessStatus: 204
};

// Development CORS Settings
const developmentCors = {
  origin: 'http://localhost:3001',
  credentials: true
};
```

### 8. **Request Size Limits**
```javascript
// Prevent large payload attacks
app.use(express.json({ limit: '10kb' }));      // JSON payload limit
app.use(express.urlencoded({ limit: '10kb' })); // Form data limit

// For file uploads (if needed)
const upload = multer({
  limits: {
    fileSize: 5 * 1024 * 1024, // 5MB max file size
    files: 1                    // 1 file at a time
  },
  fileFilter: (req, file, cb) => {
    // Only allow specific file types
    const allowedTypes = ['image/jpeg', 'image/png', 'application/pdf'];
    if (allowedTypes.includes(file.mimetype)) {
      cb(null, true);
    } else {
      cb(new Error('Invalid file type'), false);
    }
  }
});
```

### 9. **Monitoring and Alerting**
```javascript
// Security Event Monitoring
const securityEvents = {
  failedAuth: (ip, user, reason) => {
    logSecurityEvent('AUTH_FAILURE', { ip, user, reason });
    if (exceedsThreshold('failed_auth', ip)) {
      blockIP(ip);
      alertSecurityTeam('Multiple auth failures', { ip, count: getCount(ip) });
    }
  },

  rateLimitHit: (ip, endpoint) => {
    logSecurityEvent('RATE_LIMIT', { ip, endpoint });
    alertSecurityTeam('Rate limit exceeded', { ip, endpoint });
  },

  suspiciousInput: (ip, input, pattern) => {
    logSecurityEvent('SUSPICIOUS_INPUT', { ip, input, pattern });
    // Can trigger additional validation or blocking
  }
};
```

### 10. **Environment-Specific Configuration**
```bash
# .env.production
NODE_ENV=production
PORT=443
CORS_ORIGIN=https://yourdomain.com
RATE_LIMIT_WINDOW=900000  # 15 minutes
RATE_LIMIT_MAX=100
LOG_LEVEL=warn

# .env.development
NODE_ENV=development
PORT=3000
CORS_ORIGIN=http://localhost:3001
RATE_LIMIT_WINDOW=60000   # 1 minute (for testing)
RATE_LIMIT_MAX=1000
LOG_LEVEL=debug
```

### 11. **Regular Security Maintenance Tasks**

```javascript
// Security Maintenance Checklist
const securityMaintenance = {
  weekly: [
    'Check dependency vulnerabilities (npm audit)',
    'Review security logs',
    'Update security headers configuration',
    'Test rate limiting effectiveness'
  ],

  monthly: [
    'Rotate API keys and secrets',
    'Review and update CORS policies',
    'Audit error logs for patterns',
    'Test security middleware',
    'Update Helmet.js configuration'
  ],

  quarterly: [
    'Full security audit',
    'Penetration testing',
    'Update all dependencies',
    'Review and update validation rules',
    'Test disaster recovery procedures'
  ]
};
```

### 12. **Testing Security Features**

```javascript
// Security Test Suite Examples
const securityTests = {
  headers: {
    testCSP: 'Check Content-Security-Policy header',
    testHSTS: 'Verify Strict-Transport-Security',
    testXFrameOptions: 'Confirm clickjacking protection'
  },

  inputValidation: {
    testSQLInjection: 'Attempt SQL injection payloads',
    testXSS: 'Test cross-site scripting attempts',
    testPathTraversal: 'Try directory traversal attacks'
  },

  rateLimiting: {
    testFloodProtection: 'Send rapid requests',
    testBurstHandling: 'Test burst request handling'
  },

  errorHandling: {
    testErrorDisclosure: 'Verify no stack traces in production',
    testGracefulDegradation: 'Test under load conditions'
  }
};
```

## Implementation Priority

### High Priority (Must Have)
1. Input validation and sanitization
2. Security headers (Helmet.js)
3. Rate limiting
4. Error handling without information disclosure

### Medium Priority (Should Have)
1. CORS configuration
2. Request size limits
3. Structured logging
4. Request validation middleware

### Low Priority (Nice to Have)
1. Advanced monitoring and alerting
2. Custom security middleware
3. Comprehensive security testing
4. Automated vulnerability scanning

## Key Takeaways

1. **Security is a process, not a product** - Regular maintenance is required
2. **Defense in depth** - Multiple layers of security
3. **Validate early, validate often** - Input validation at every stage
4. **Fail securely** - Graceful degradation under attack
5. **Monitor everything** - Comprehensive logging and alerting
6. **Keep it simple** - Complex security is often less secure
7. **Stay updated** - Regular dependency and configuration updates

This configuration provides a robust security foundation that can be extended based on specific application requirements and threat models.

// Enhanced Express application with basic error handling and security
// This version demonstrates key improvements without external dependencies

const express = require('express');
const app = express();

// ==================== BASIC SECURITY MIDDLEWARE ====================

// Set basic security headers (simplified version of Helmet)
app.use((req, res, next) => {
  // Hide Express version
  res.setHeader('X-Powered-By', 'Custom Server');

  // Prevent MIME sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Basic XSS protection
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  next();
});

// Parse JSON with size limit
app.use(express.json({ limit: '10kb' }));

// Parse URL-encoded data with size limit
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ==================== CUSTOM VALIDATION MIDDLEWARE ====================

// Basic rate limiting
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();
  const windowMs = 15 * 60 * 1000; // 15 minutes
  const maxRequests = 100;

  if (!requestCounts.has(ip)) {
    requestCounts.set(ip, []);
  }

  // Clean old requests
  const requests = requestCounts.get(ip).filter(time => now - time < windowMs);
  requestCounts.set(ip, requests);

  if (requests.length >= maxRequests) {
    return res.status(429).json({
      status: 'error',
      message: 'Too many requests, please try again later.'
    });
  }

  requests.push(now);
  next();
});

// Input sanitization
const sanitizeInput = (req, res, next) => {
  // Remove potentially dangerous characters from query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        // Basic sanitization - remove HTML tags and dangerous characters
        req.query[key] = req.query[key]
          .replace(/</g, '&lt;')
          .replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;')
          .replace(/'/g, '&#x27;')
          .replace(/`/g, '&#x60;');
      }
    });
  }

  // Sanitize request body strings
  if (req.body && typeof req.body === 'object') {
    const sanitizeObject = (obj) => {
      Object.keys(obj).forEach(key => {
        if (typeof obj[key] === 'string') {
          obj[key] = obj[key]
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
        } else if (typeof obj[key] === 'object' && obj[key] !== null) {
          sanitizeObject(obj[key]);
        }
      });
    };
    sanitizeObject(req.body);
  }

  next();
};

// Query parameter validation
const validateQueryParams = (req, res, next) => {
  const { limit, page } = req.query;

  // Validate limit parameter
  if (limit !== undefined) {
    const numLimit = Number(limit);
    if (isNaN(numLimit) || !Number.isInteger(numLimit) || numLimit < 1 || numLimit > 100) {
      return res.status(400).json({
        status: 'error',
        message: 'Limit must be an integer between 1 and 100'
      });
    }
  }

  // Validate page parameter
  if (page !== undefined) {
    const numPage = Number(page);
    if (isNaN(numPage) || !Number.isInteger(numPage) || numPage < 1) {
      return res.status(400).json({
        status: 'error',
        message: 'Page must be a positive integer'
      });
    }
  }

  next();
};

// ==================== ERROR HANDLING MIDDLEWARE ====================

