  console.log(`  Valid: ${!error}`);
  if (error) console.log(`  Error: ${error.details[0].message}`);
  console.log('');
});

// Test 6: Input with extra fields (should be rejected when allowUnknown: false)
console.log('Test 6: Extra fields');
const extraFields = {
  name: 'Extra User',
  email: 'extra@example.com',
  age: 40,
  role: 'user',
  isAdmin: true,
  password: 'secret'
};
const { error: error6, value: value6 } = createUserSchema.validate(extraFields, {
  allowUnknown: false,
  abortEarly: false
});
console.log('Valid:', !error6);
if (error6) console.log('Error (extra fields rejected):', error6.details.map(d => d.message));

console.log('\n=== Security Best Practices Summary ===');
console.log('1. All user inputs are validated against a schema');
console.log('2. Inputs are sanitized before processing');
console.log('3. Size limits prevent DoS via large payloads');
console.log('4. Type checking prevents injection attacks');
console.log('5. Rate limiting protects against brute force');
console.log('6. CORS restricts allowed origins');
console.log('7. Security headers protect against common web vulnerabilities');

