// Improved application with security best practices
// Enhanced error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const expressSanitizer = require('express-sanitizer');
const Joi = require('joi');

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Enable CORS with secure configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : [],
  credentials: true,
  optionsSuccessStatus: 200
}));

// Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use('/api/', apiLimiter);

// Body parser middleware with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input sanitization
app.use(expressSanitizer());

// Validate environment variables
const envSchema = Joi.object({
  NODE_ENV: Joi.string().valid('development', 'production', 'test').default('development'),
  PORT: Joi.number().port().default(3000),
  DATABASE_URL: Joi.string().uri().when('NODE_ENV', {
    is: 'production',
    then: Joi.required()
  }),
  ALLOWED_ORIGINS: Joi.string().optional(),
}).unknown(); // Allow other env vars

const { error: envError } = envSchema.validate(process.env);
if (envError) {
  console.error('Environment validation error:', envError.details);
  process.exit(1);
}

// Custom error handling middleware
app.use((err, req, res, next) => {
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: 'Invalid JSON payload',
      message: 'Please provide valid JSON data'
    });
  }
  next(err);
});

// Input validation schemas
const userIdSchema = Joi.object({
  id: Joi.number().integer().min(1).required()
});

const userQuerySchema = Joi.object({
  page: Joi.number().integer().min(1).default(1),
  limit: Joi.number().integer().min(1).max(100).default(10),
  sort: Joi.string().valid('name', 'id', 'createdAt').default('id'),
  order: Joi.string().valid('asc', 'desc').default('asc')
});

// Validation middleware
const validate = (schema, property = 'body') => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req[property], {
      abortEarly: false,
      allowUnknown: false
    });

    if (error) {
      return res.status(400).json({
        error: 'Validation failed',
        details: error.details.map(detail => ({
          path: detail.path.join('.'),
          message: detail.message
        }))
      });
    }

    // Replace validated values
    req[property] = value;
    next();
  };
};

// Routes with improved error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ status: 'error', message: 'Internal server error' });
  }
});

app.get('/users', validate(userQuerySchema, 'query'), (req, res) => {
  try {
    const { page, limit, sort, order } = req.query;

    // Simulate database query with pagination
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: '2024-01-01' },
      { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: '2024-01-02' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', createdAt: '2024-01-03' },
      { id: 4, name: 'David', email: 'david@example.com', createdAt: '2024-01-04' },
      { id: 5, name: 'Eve', email: 'eve@example.com', createdAt: '2024-01-05' },
    ];

    // Sort users
    const sortedUsers = [...allUsers].sort((a, b) => {
      const aVal = a[sort];
      const bVal = b[sort];
      return order === 'asc' ? 
        (aVal < bVal ? -1 : aVal > bVal ? 1 : 0) :
        (bVal < aVal ? -1 : bVal > aVal ? 1 : 0);
    });

    // Paginate
    const start = (page - 1) * limit;
    const end = start + limit;
    const paginatedUsers = sortedUsers.slice(start, end);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: allUsers.length,
        totalPages: Math.ceil(allUsers.length / limit),
        hasNext: end < allUsers.length,
        hasPrev: page > 1
      }
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An unexpected error occurred while fetching users'
    });
  }
});

app.get('/users/:id', validate(userIdSchema, 'params'), (req, res) => {
  try {
    const { id } = req.params;

    // Simulate database lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === parseInt(id));

    if (!user) {
      return res.status(404).json({
        error: 'User not found',
        message: `User with ID ${id} does not exist`
      });
    }

    res.json(user);
  } catch (error) {
    console.error('User detail endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An unexpected error occurred while fetching user details'
    });
  }
});

// POST endpoint with comprehensive validation
const createUserSchema = Joi.object({
  name: Joi.string().min(1).max(100).trim().required(),
  email: Joi.string().email().lowercase().trim().required(),
  age: Joi.number().integer().min(0).max(150).optional(),
  role: Joi.string().valid('user', 'admin', 'moderator').default('user')
});

app.post('/users', validate(createUserSchema), (req, res) => {
  try {
    const { name, email, age, role } = req.body;

    // Additional security check: sanitize output
    const sanitizedUser = {
      id: Date.now(),
      name: req.sanitize(name),
      email: req.sanitize(email),
      age,
      role,
      createdAt: new Date().toISOString()
    };

    // In production, you would save to database here

    res.status(201).json({
      message: 'User created successfully',
      user: sanitizedUser
    });
  } catch (error) {
    console.error('Create user error:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to create user'
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `The requested resource ${req.originalUrl} was not found`
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't leak stack traces in production
  const isProduction = process.env.NODE_ENV === 'production';

  if (err.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation error',
      message: err.message
    });
  }

  if (err.name === 'UnauthorizedError') {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Invalid or missing authentication'
    });
  }

  res.status(500).json({
    error: 'Internal server error',
    message: isProduction ? 'An unexpected error occurred' : err.message
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

// Start server with error handling
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running securely on port ${PORT}`);
}).on('error', (err) => {
  if (err.code === 'EADDRINUSE') {
    console.error(`Port ${PORT} is already in use`);
  } else {
    console.error('Server startup error:', err);
  }
  process.exit(1);
});

module.exports = app;

