// Improved Express application with comprehensive security measures
// This version includes proper error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const expressValidator = require('express-validator');
const { body, validationResult } = require('express-validator');
const { v4: uuidv4 } = require('uuid');

const app = express();

// ====================
// SECURITY MIDDLEWARE
// ====================

// 1. Helmet.js for setting secure HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  xssFilter: true, // Enable XSS filtering
  nosniff: true, // Prevent MIME type sniffing
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
}));

// 2. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// 3. CORS configuration (adjust for your specific needs)
app.use(cors({
  origin: process.env.NODE_ENV === 'production' 
    ? ['https://yourdomain.com'] 
    : ['http://localhost:3000', 'http://localhost:8080'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
}));

// 4. Parse JSON bodies with size limit
app.use(express.json({ limit: '10kb' }));

// 5. Parse URL-encoded bodies with extended: false for security
app.use(express.urlencoded({ extended: false }));

// ====================
// LOGGING MIDDLEWARE
// ====================

// Request ID for tracking
app.use((req, res, next) => {
  req.id = uuidv4();
  next();
});

// Basic request logging
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.id} - ${req.method} ${req.url}`);
  next();
});

// ====================
// ERROR HANDLING MIDDLEWARE
// ====================

// Centralized error handler
const errorHandler = (err, req, res, next) => {
  console.error(`${new Date().toISOString()} - ${req.id || 'no-id'} - Error:`, err);

  // Don't leak stack traces in production
  const errorResponse = {
    error: 'An unexpected error occurred',
    requestId: req.id,
    timestamp: new Date().toISOString(),
  };

  if (process.env.NODE_ENV === 'development') {
    errorResponse.message = err.message;
    errorResponse.stack = err.stack;
  }

  res.status(err.statusCode || 500).json(errorResponse);
};

// ====================
// VALIDATION MIDDLEWARE
// ====================

// Validation error handler
const validate = (validations) => {
  return async (req, res, next) => {
    try {
      await Promise.all(validations.map(validation => validation.run(req)));

      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          error: 'Validation failed',
          details: errors.array(),
          requestId: req.id,
        });
      }

      next();
    } catch (error) {
      next(error);
    }
  };
};

// ====================
// ROUTES WITH VALIDATION
// ====================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    const healthData = {
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memoryUsage: process.memoryUsage(),
      requestId: req.id,
    };

    res.json(healthData);
  } catch (error) {
    console.error(`Health check error: ${error.message}`);
    res.status(500).json({
      status: 'unhealthy',
      error: 'Health check failed',
      requestId: req.id,
    });
  }
});

// Users endpoint with parameter validation
app.get('/users', [
  // Validate query parameters
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  body('sort').optional().isIn(['id', 'name', 'email']).withMessage('Invalid sort field'),
], validate([]), (req, res, next) => {
  try {
    // Extract and sanitize query parameters
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const page = parseInt(req.query.page) || 1;
    const offset = (page - 1) * limit;
    const sort = req.query.sort || 'id';

    // Simulated user data (in real app, fetch from database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Apply sorting (in real app, do this in database query)
    const sortedUsers = [...allUsers].sort((a, b) => {
      if (sort === 'id') return a.id - b.id;
      if (sort === 'name') return a.name.localeCompare(b.name);
      if (sort === 'email') return a.email.localeCompare(b.email);
      return 0;
    });

    // Apply pagination
    const paginatedUsers = sortedUsers.slice(offset, offset + limit);

    res.json({
      users: paginatedUsers,
      pagination: {
        total: allUsers.length,
        page,
        limit,
        totalPages: Math.ceil(allUsers.length / limit),
      },
      requestId: req.id,
    });

  } catch (error) {
    next(error);
  }
});

// New endpoint: Get user by ID with parameter validation
app.get('/users/:id', [
  // Validate path parameter
  body('id').custom((value, { req }) => {
    const id = parseInt(req.params.id);
    if (isNaN(id) || id <= 0) {
      throw new Error('User ID must be a positive integer');
    }
    return true;
  }),
], validate([]), (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);

    // Simulated user lookup (in real app, fetch from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      const error = new Error('User not found');
      error.statusCode = 404;
      throw error;
    }

    res.json({
      user,
      requestId: req.id,
    });

  } catch (error) {
    next(error);
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.originalUrl,
    method: req.method,
    requestId: req.id,
    timestamp: new Date().toISOString(),
  });
});

// Apply error handling middleware
app.use(errorHandler);

// ====================
// SERVER SETUP WITH ERROR HANDLING
// ====================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Graceful shutdown handler
const gracefulShutdown = (signal) => {
  console.log(`${signal} received. Starting graceful shutdown...`);
  server.close(() => {
    console.log('HTTP server closed.');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Force shutdown after timeout');
    process.exit(1);
  }, 10000);
};

// Start server with error handling
const startServer = async () => {
  try {
    const server = app.listen(PORT, () => {
      console.log(`Server running in ${NODE_ENV} mode on port ${PORT}`);
      console.log(`Request ID pattern enabled`);
    });

    // Handle graceful shutdown
    process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
    process.on('SIGINT', () => gracefulShutdown('SIGINT'));

    // Handle uncaught exceptions
    process.on('uncaughtException', (error) => {
      console.error('Uncaught Exception:', error);
      gracefulShutdown('UNCAUGHT_EXCEPTION');
    });

    // Handle unhandled promise rejections
    process.on('unhandledRejection', (reason, promise) => {
      console.error('Unhandled Rejection at:', promise, 'reason:', reason);
      gracefulShutdown('UNHANDLED_REJECTION');
    });

    return server;
  } catch (error) {
    console.error('Failed to start server:', error);
    process.exit(1);
  }
};

// Export for testing
module.exports = { app, startServer };

// Start server if this file is run directly
if (require.main === module) {
  startServer();
}

// Test script to verify security improvements

const { app } = require('./app_improved.js');
const request = require('supertest');

async function runSecurityTests() {
  console.log('=== Security Features Test Suite ===\n');

  // Test 1: Verify security headers
  console.log('1. Testing Security Headers...');
  const headersResponse = await request(app).get('/health');
