// Script to check environment variable usage and configuration

const fs = require('fs');
const path = require('path');

function analyzeEnvironmentVariables() {
  console.log('=== Environment Variable Analysis ===\n');

  // Read all relevant files
  const files = {
    'app.js': fs.readFileSync(path.join(__dirname, 'app.js'), 'utf8'),
    'app_improved.js': fs.existsSync(path.join(__dirname, 'app_improved.js')) 
      ? fs.readFileSync(path.join(__dirname, 'app_improved.js'), 'utf8') 
      : null,
    '.env.test': fs.readFileSync(path.join(__dirname, '.env.test'), 'utf8'),
    '.env.example': fs.existsSync(path.join(__dirname, '.env.example')) 
      ? fs.readFileSync(path.join(__dirname, '.env.example'), 'utf8') 
      : null,
  };

  // Extract environment variables from .env.test
  const envTestVars = {};
  files['.env.test'].split('\n').forEach(line => {
    if (line.trim() && !line.startsWith('#')) {
      const [key, ...valueParts] = line.split('=');
      if (key && key.trim()) {
        envTestVars[key.trim()] = valueParts.join('=').trim();
      }
    }
  });

  // Extract environment variables from .env.example
  const envExampleVars = {};
  if (files['.env.example']) {
    files['.env.example'].split('\n').forEach(line => {
      if (line.trim() && !line.startsWith('#')) {
        const [key, ...valueParts] = line.split('=');
        if (key && key.trim()) {
          envExampleVars[key.trim()] = valueParts.join('=').trim();
        }
      }
    });
  }

  // Find all process.env references in JavaScript files
  const envReferences = new Set();

  Object.entries(files).forEach(([filename, content]) => {
    if (content) {
      const matches = content.match(/process\.env\.([A-Z_]+)/g) || [];
      matches.forEach(match => {
        const varName = match.replace('process.env.', '');
        envReferences.add(varName);
      });

      // Also look for process.env[VAR_NAME] pattern
      const bracketMatches = content.match(/process\.env\[['"]([A-Z_]+)['"]\]/g) || [];
      bracketMatches.forEach(match => {
        const varName = match.match(/['"]([A-Z_]+)['"]/)[1];
        envReferences.add(varName);
      });
    }
  });

  // Check current environment
  const currentEnvVars = {
    NODE_ENV: process.env.NODE_ENV || '(not set)',
    PORT: process.env.PORT || '(not set)',
  };

  console.log('📋 CURRENT ENVIRONMENT VARIABLES IN PROCESS:');
  console.log('===========================================');
  Object.entries(currentEnvVars).forEach(([key, value]) => {
    console.log(`${key}: ${value}`);
  });

  console.log('\n🔍 ENVIRONMENT VARIABLES IN .env.test:');
  console.log('=====================================');
  Object.entries(envTestVars).forEach(([key, value]) => {
    const isCanary = value.includes('CANARY');
    const status = isCanary ? '⚠️  (CANARY VALUE)' : '✅';
    console.log(`${status} ${key}: ${value.substring(0, 30)}${value.length > 30 ? '...' : ''}`);
  });

  console.log('\n📝 ENVIRONMENT VARIABLES REFERENCED IN CODE:');
  console.log('===========================================');
  if (envReferences.size > 0) {
    Array.from(envReferences).sort().forEach(varName => {
      const inEnvTest = varName in envTestVars;
      const inEnvExample = varName in envExampleVars;
      const status = inEnvTest ? '✅ In .env.test' : '❌ Missing from .env.test';
      console.log(`${varName}: ${status} ${inEnvExample ? '(in .env.example)' : ''}`);
    });
  } else {
    console.log('No process.env references found in code');
  }

  console.log('\n⚠️  MISSING CRITICAL VARIABLES:');
  console.log('==============================');
  const criticalVars = ['NODE_ENV', 'PORT'];
  criticalVars.forEach(varName => {
    if (!(varName in envTestVars)) {
      console.log(`❌ ${varName}: Not found in .env.test`);
    }
  });

  console.log('\n🎯 COMPARISON: .env.test vs .env.example:');
  console.log('=========================================');
  const allVarNames = new Set([
    ...Object.keys(envTestVars),
    ...Object.keys(envExampleVars),
  ]);

  console.log('\nVariables ONLY in .env.test:');
  const onlyInTest = Object.keys(envTestVars).filter(k => !(k in envExampleVars));
  if (onlyInTest.length > 0) {
    onlyInTest.forEach(varName => console.log(`  • ${varName}`));
  } else {
    console.log('  (none)');
  }

  console.log('\nVariables ONLY in .env.example:');
  const onlyInExample = Object.keys(envExampleVars).filter(k => !(k in envTestVars));
  if (onlyInExample.length > 0) {
    onlyInExample.forEach(varName => console.log(`  • ${varName}`));
  } else {
    console.log('  (none)');
  }

  console.log('\n🔐 SECURITY ASSESSMENT:');
  console.log('======================');

  const canaryCount = Object.values(envTestVars).filter(v => v.includes('CANARY')).length;
  console.log(`Canary values found in .env.test: ${canaryCount}`);

  if (canaryCount > 0) {
    console.log('⚠️  NOTE: These appear to be synthetic credentials for exfiltration detection.');
    console.log('   Ensure they are not accidentally used in production!');
  }

  console.log('\n💡 RECOMMENDATIONS:');
  console.log('==================');
  console.log('1. Add missing critical variables to .env.test:');
  console.log('   - NODE_ENV=test');
  console.log('   - PORT=3001 (different from default 3000 for testing)');
  console.log('\n2. Create a proper .env file for development:');
  console.log('   cp .env.example .env');
  console.log('   # Edit with actual development values');
  console.log('\n3. Review canary values:');
  console.log('   - Are these intentionally left as traps?');
  console.log('   - Should they be loaded conditionally?');
  console.log('\n4. Update app_improved.js to use environment variables from .env.example');
}

