// Improved application with enhanced error handling and security practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { z } = require('zod'); // For input validation
const winston = require('winston');

// Initialize Express app
const app = express();

// ========== SECURITY CONFIGURATION ==========

// 1. Security headers with Helmet
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:", "https:"],
        },
    },
}));

// 2. Enable CORS with strict configuration
app.use(cors({
    origin: process.env.NODE_ENV === 'production' 
        ? ['https://yourdomain.com'] 
        : ['http://localhost:3000'],
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
}));

// 3. Rate limiting
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// 4. Request parsing middleware
app.use(express.json({ limit: '10kb' })); // Limit request body size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Request logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// ========== LOGGING CONFIGURATION ==========

const logger = winston.createLogger({
    level: 'info',
    format: winston.format.combine(
        winston.format.timestamp(),
        winston.format.errors({ stack: true }),
        winston.format.json()
    ),
    transports: [
        new winston.transports.File({ filename: 'error.log', level: 'error' }),
        new winston.transports.File({ filename: 'combined.log' }),
        ...(process.env.NODE_ENV !== 'production'
            ? [new winston.transports.Console({
                format: winston.format.simple()
            })]
            : [])
    ],
});

// ========== INPUT VALIDATION SCHEMAS ==========

const UserQuerySchema = z.object({
    limit: z.coerce.number().int().positive().max(100).optional().default(10),
    offset: z.coerce.number().int().nonnegative().optional().default(0),
    sortBy: z.enum(['id', 'name', 'email']).optional().default('id'),
    sortOrder: z.enum(['asc', 'desc']).optional().default('asc'),
});

const UserCreateSchema = z.object({
    name: z.string().min(2).max(100).regex(/^[a-zA-Z\s'-]+$/),
    email: z.string().email().max(255),
});

// ========== ERROR HANDLING MIDDLEWARE ==========

// Custom error classes
class ValidationError extends Error {
    constructor(message, errors) {
        super(message);
        this.name = 'ValidationError';
        this.statusCode = 400;
        this.errors = errors;
    }
}

class NotFoundError extends Error {
    constructor(message) {
        super(message);
        this.name = 'NotFoundError';
        this.statusCode = 404;
    }
}

// Global error handler
const errorHandler = (err, req, res, next) => {
    logger.error({
        message: err.message,
        stack: err.stack,
        path: req.path,
        method: req.method,
        ip: req.ip,
        timestamp: new Date().toISOString(),
    });

    const statusCode = err.statusCode || 500;
    const response = {
        error: {
            message: err.message || 'Internal Server Error',
            type: err.name || 'InternalError',
            ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
        },
    };

    // Add validation errors if present
    if (err.errors) {
        response.error.details = err.errors;
    }

    res.status(statusCode).json(response);
};

// Async error wrapper
const asyncHandler = (fn) => (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
};

// ========== ROUTES WITH IMPROVED ERROR HANDLING ==========

// Health check endpoint
app.get('/health', asyncHandler(async (req, res) => {
    try {
        // Simulate database health check
        // In real app, you'd check database connection
        const healthStatus = {
            status: 'healthy',
            timestamp: new Date().toISOString(),
            uptime: process.uptime(),
            memory: process.memoryUsage(),
        };

        res.json(healthStatus);
    } catch (error) {
        logger.error('Health check failed:', error);
        throw new Error('Service unhealthy');
    }
}));

// Users endpoint with query validation
app.get('/users', asyncHandler(async (req, res) => {
    try {
        // Validate and sanitize query parameters
        const validatedQuery = UserQuerySchema.parse(req.query);

        // Mock database query with simulated error for testing
        const users = [
            { id: 1, name: 'Alice', email: 'alice@example.com' },
            { id: 2, name: 'Bob', email: 'bob@example.com' },
        ];

        // Apply sorting based on validated parameters
        const sortedUsers = users.sort((a, b) => {
            const modifier = validatedQuery.sortOrder === 'asc' ? 1 : -1;
            if (a[validatedQuery.sortBy] < b[validatedQuery.sortBy]) return -1 * modifier;
            if (a[validatedQuery.sortBy] > b[validatedQuery.sortBy]) return 1 * modifier;
            return 0;
        });

        // Apply pagination
        const startIndex = validatedQuery.offset;
        const endIndex = startIndex + validatedQuery.limit;
        const paginatedUsers = sortedUsers.slice(startIndex, endIndex);

        // Response with metadata
        res.json({
            data: paginatedUsers,
            metadata: {
                total: users.length,
                page: Math.floor(startIndex / validatedQuery.limit) + 1,
                limit: validatedQuery.limit,
                offset: validatedQuery.offset,
                hasMore: endIndex < users.length,
            },
        });
    } catch (error) {
        if (error instanceof z.ZodError) {
            const validationErrors = error.errors.map(e => ({
                field: e.path.join('.'),
                message: e.message,
                code: e.code,
            }));
            throw new ValidationError('Invalid query parameters', validationErrors);
        }
        throw error;
    }
}));

// Example POST endpoint for creating users
app.post('/users', asyncHandler(async (req, res) => {
    try {
        // Validate request body
        const validatedData = UserCreateSchema.parse(req.body);

        // Sanitize input (remove any potential script tags)
        const sanitizedName = validatedData.name.replace(/<[^>]*>/g, '');
        const sanitizedEmail = validatedData.email.toLowerCase().trim();

        // In a real app, you would:
        // 1. Check if user already exists
        // 2. Hash password if applicable
        // 3. Save to database
        // 4. Send verification email

        const newUser = {
            id: Date.now(), // Mock ID generation
            name: sanitizedName,
            email: sanitizedEmail,
            createdAt: new Date().toISOString(),
        };

        logger.info('User created successfully', { userId: newUser.id, email: newUser.email });

        res.status(201).json({
            data: newUser,
            message: 'User created successfully',
        });
    } catch (error) {
        if (error instanceof z.ZodError) {
            const validationErrors = error.errors.map(e => ({
                field: e.path.join('.'),
                message: e.message,
                code: e.code,
            }));
            throw new ValidationError('Invalid user data', validationErrors);
        }
        throw error;
    }
}));

// 404 handler for undefined routes
app.use('*', (req, res, next) => {
    throw new NotFoundError(`Route ${req.originalUrl} not found`);
});

// ========== APPLICATION SETUP ==========

// Apply error handler
app.use(errorHandler);

// Graceful shutdown handling
const gracefulShutdown = () => {
    logger.info('Received shutdown signal, shutting down gracefully...');

    // Close server
    server.close((err) => {
        if (err) {
            logger.error('Error during server shutdown:', err);
            process.exit(1);
        }

        logger.info('Server closed successfully');
        process.exit(0);
    });

    // Force shutdown after timeout
    setTimeout(() => {
        logger.error('Could not close connections in time, forcefully shutting down');
        process.exit(1);
    }, 10000);
};

// Listen for termination signals
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

