// Focused improvements for app.js - Error handling and input validation

const express = require('express');
const app = express();

// ========== BASIC INPUT VALIDATION MIDDLEWARE ==========

// Validate query parameters middleware
const validateQueryParams = (req, res, next) => {
    // Validate numeric parameters
    const { limit, offset } = req.query;

    if (limit) {
        const limitNum = parseInt(limit);
        if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
            return res.status(400).json({
                error: 'Invalid limit parameter. Must be a number between 1 and 100'
            });
        }
    }

    if (offset) {
        const offsetNum = parseInt(offset);
        if (isNaN(offsetNum) || offsetNum < 0) {
            return res.status(400).json({
                error: 'Invalid offset parameter. Must be a non-negative number'
            });
        }
    }

    next();
};

// Basic error handler middleware
const errorHandler = (err, req, res, next) => {
    console.error('Error:', err.message);

    // Don't expose stack traces in production
    const errorResponse = {
        error: 'Internal Server Error'
    };

    if (process.env.NODE_ENV === 'development') {
        errorResponse.message = err.message;
        errorResponse.stack = err.stack;
    }

    res.status(500).json(errorResponse);
};

// ========== IMPROVED ROUTES WITH ERROR HANDLING ==========

app.get('/health', (req, res) => {
    try {
        // Basic health check with error simulation
        res.json({ 
            status: 'ok', 
            timestamp: new Date().toISOString() 
        });
    } catch (error) {
        // Log error internally
        console.error('Health check failed:', error);
        res.status(503).json({ 
            status: 'error', 
            message: 'Service unavailable' 
        });
    }
});

// Users endpoint with query validation
app.get('/users', validateQueryParams, (req, res) => {
    try {
        // Parse and validate query parameters
