// Enhanced application with security best practices
// Improved error handling, input validation, and security measures

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// 1. Security Headers Middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
}));

// 2. Rate Limiting - Prevent brute force and DDoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all requests
app.use(limiter);

// 3. JSON and URL Encoding parsers with limits
app.use(express.json({ limit: '1mb' })); // Prevent large payloads
app.use(express.urlencoded({ extended: true, limit: '1mb' }));

// 4. Error Handling Middleware
const errorHandler = (err, req, res, next) => {
  console.error('Error:', {
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.url,
    error: err.message,
    stack: err.stack,
    ip: req.ip,
  });

  // Don't expose detailed error information in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: isProduction ? 'Internal server error' : err.message,
    ...(isProduction ? {} : { stack: err.stack }),
  });
};

// 5. Input Validation Middleware
const validateUserInput = [
  body('name').trim().escape().isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters'),
  body('email').trim().normalizeEmail().isEmail().withMessage('Valid email is required'),
  body('id').optional().isInt({ min: 1 }).withMessage('ID must be a positive integer'),
];

// 6. Request Validation Middleware
const validateRequest = (req, res, next) => {
  // Check content type for POST/PUT requests
  if (['POST', 'PUT', 'PATCH'].includes(req.method)) {
    if (!req.is('application/json')) {
      return res.status(415).json({ error: 'Unsupported Media Type: Only JSON is accepted' });
    }
  }
  next();
};

app.use(validateRequest);

// 7. Health endpoint with improved response
app.get('/health', (req, res) => {
  try {
    const healthData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memoryUsage: process.memoryUsage(),
      nodeVersion: process.version,
    };

    res.set('Cache-Control', 'no-cache, no-store, must-revalidate');
    res.json(healthData);
  } catch (error) {
    res.status(503).json({ status: 'error', error: 'Health check failed' });
  }
});

// 8. Users endpoint with input validation and error handling
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters if they exist
    const { limit, offset } = req.query;

    if (limit && (!Number.isInteger(Number(limit)) || Number(limit) < 1 || Number(limit) > 100)) {
      return res.status(400).json({ 
        error: 'Invalid limit parameter. Must be an integer between 1 and 100' 
      });
    }

    if (offset && (!Number.isInteger(Number(offset)) || Number(offset) < 0)) {
      return res.status(400).json({ 
        error: 'Invalid offset parameter. Must be a non-negative integer' 
      });
    }

    // Simulating database query with error handling
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply query filters
    let filteredUsers = [...users];
    if (limit) {
      filteredUsers = filteredUsers.slice(0, Number(limit));
    }

    // Set security headers for this specific response
    res.set({
      'X-Content-Type-Options': 'nosniff',
      'X-Frame-Options': 'DENY',
    });

    res.json({
      data: filteredUsers,
      meta: {
        total: users.length,
        returned: filteredUsers.length,
        limit: limit ? Number(limit) : null,
        offset: offset ? Number(offset) : 0,
      }
    });

  } catch (error) {
    next(error); // Pass to error handler middleware
  }
});

// 9. Create user endpoint with validation
app.post('/users', validateUserInput, (req, res, next) => {
  try {
    // Check validation results
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array(),
        message: 'Validation failed' 
      });
    }

    const { name, email } = req.body;

    // Sanitize and validate input
    const sanitizedName = name.trim().replace(/[<>]/g, '');
    const sanitizedEmail = email.trim().toLowerCase();

    // Create new user (in a real app, this would save to database)
    const newUser = {
      id: Date.now(), // Temporary ID generation
      name: sanitizedName,
      email: sanitizedEmail,
      createdAt: new Date().toISOString(),
    };

    res.status(201).json({
      message: 'User created successfully',
      data: newUser,
    });

  } catch (error) {
    next(error);
  }
});

// 10. Specific user endpoint with parameter validation
app.get('/users/:id', (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);

    // Validate user ID
    if (isNaN(userId) || userId < 1) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    // Simulate database lookup
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json({ data: user });

  } catch (error) {
    next(error);
  }
});

// 11. Logging middleware - log all requests
app.use((req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    console.log('Request:', {
      timestamp: new Date().toISOString(),
      method: req.method,
      url: req.url,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent'),
    });
  });

  next();
});

// 12. Apply error handler middleware
app.use(errorHandler);

// 13. 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Endpoint not found',
    message: `The requested resource ${req.url} was not found on this server`,
  });
});

// 14. Server startup with error handling
const startServer = () => {
  const PORT = process.env.PORT || 3000;

  app.listen(PORT, (error) => {
    if (error) {
      console.error('Failed to start server:', error);
      process.exit(1);
    }

    console.log(`Server running securely on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
};

// Handle uncaught exceptions and unhandled rejections
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

module.exports = { app, startServer };

// Start server if this file is run directly
if (require.main === module) {
  startServer();
}

