// Enhanced application with security best practices
// Improved error handling and input validation

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const compression = require('compression');
const expressSanitizer = require('express-sanitizer');
const morgan = require('morgan');
const app = express();

// Security Headers Configuration
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:"],
        },
    },
    crossOriginEmbedderPolicy: false, // Can be adjusted based on requirements
}));

// CORS Configuration
const corsOptions = {
    origin: process.env.NODE_ENV === 'production' 
        ? process.env.ALLOWED_ORIGINS?.split(',') || ['https://example.com']
        : '*', // Allow all in development
    optionsSuccessStatus: 200,
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
};
app.use(cors(corsOptions));

// Rate Limiting
const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // Limit each IP to 100 requests per windowMs
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// Apply stricter rate limiting to sensitive endpoints
const strictLimiter = rateLimit({
    windowMs: 5 * 60 * 1000, // 5 minutes
    max: 20, // Limit each IP to 20 requests per windowMs for sensitive endpoints
    message: 'Too many requests to sensitive endpoints, please try again later.',
});

// Compression for performance
app.use(compression());

// Request parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' })); // Limit URL-encoded payload

// Sanitize inputs to prevent XSS attacks
app.use(expressSanitizer());

// Structured logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Environment Validation
const validateEnvironment = () => {
    const requiredEnvVars = ['NODE_ENV', 'PORT'];
    const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);

    if (missingVars.length > 0) {
        console.error(`Missing required environment variables: ${missingVars.join(', ')}`);
        process.exit(1);
    }

    // Validate environment
    const allowedEnvs = ['development', 'test', 'production'];
    if (!allowedEnvs.includes(process.env.NODE_ENV)) {
        console.error(`Invalid NODE_ENV: ${process.env.NODE_ENV}. Must be one of: ${allowedEnvs.join(', ')}`);
        process.exit(1);
    }
};

// Input Validation Middleware
const validateQueryParams = (req, res, next) => {
    // Common query parameter validation
    const { limit, offset, sort } = req.query;

    // Validate numeric parameters
    if (limit && !/^\d+$/.test(limit)) {
        return res.status(400).json({ error: 'Limit parameter must be a positive integer' });
    }

    if (offset && !/^\d+$/.test(offset)) {
        return res.status(400).json({ error: 'Offset parameter must be a non-negative integer' });
    }

    // Validate sort parameter (only allow alphanumeric and underscore)
    if (sort && !/^[a-zA-Z0-9_]+$/.test(sort)) {
        return res.status(400).json({ error: 'Sort parameter contains invalid characters' });
    }

    next();
};

// Validate email format
const validateEmail = (email) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
};

// Centralized Error Handling Middleware
const errorHandler = (err, req, res, next) => {
    console.error(`[ERROR] ${new Date().toISOString()} - ${req.method} ${req.url}`);
    console.error(err.stack);

    // Handle different error types
    if (err.type === 'entity.too.large') {
        return res.status(413).json({ 
            error: 'Payload too large',
            message: 'Request body exceeds the allowed size limit'
        });
    }

    if (err.name === 'ValidationError') {
        return res.status(400).json({ 
            error: 'Validation Error',
            message: err.message 
        });
    }

    // Default error response
    const statusCode = err.statusCode || 500;
    const message = process.env.NODE_ENV === 'production' 
        ? 'An unexpected error occurred' 
        : err.message;

    res.status(statusCode).json({
        error: 'Internal Server Error',
        message,
        ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
    });
};

// Not Found Handler
const notFoundHandler = (req, res, next) => {
    res.status(404).json({
        error: 'Not Found',
        message: `Route ${req.method} ${req.url} not found`
    });
};

