// Enhanced version of app.js with security improvements
// Focuses ONLY on error handling and input validation as requested

const express = require('express');
const app = express();

// ====================
// MIDDLEWARE IMPROVEMENTS
// ====================

// 1. BASIC SECURITY HEADERS (without helmet dependency)
app.use((req, res, next) => {
    // Essential security headers
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('X-Frame-Options', 'DENY');
    res.setHeader('X-XSS-Protection', '1; mode=block');
    res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
    next();
});

// 2. REQUEST SIZE LIMITS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 3. INPUT VALIDATION MIDDLEWARE
const validateQueryParams = (req, res, next) => {
    const errors = [];

    // Validate common query parameters
    if (req.query.limit && !/^\d+$/.test(req.query.limit)) {
        errors.push('limit must be a positive integer');
    }

    if (req.query.offset && !/^\d+$/.test(req.query.offset)) {
        errors.push('offset must be a non-negative integer');
    }

    if (req.query.sort && !/^[a-zA-Z0-9_]+$/.test(req.query.sort)) {
        errors.push('sort parameter contains invalid characters');
    }

    if (errors.length > 0) {
        return res.status(400).json({
            error: 'Validation Error',
            messages: errors
        });
    }

    // Sanitize inputs (basic XSS prevention)
    for (const key in req.query) {
        if (typeof req.query[key] === 'string') {
            req.query[key] = req.query[key]
                .replace(/</g, '&lt;')
                .replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;')
                .replace(/'/g, '&#x27;');
        }
    }

    next();
};

// 4. ERROR HANDLING MIDDLEWARE
const errorHandler = (err, req, res, next) => {
    console.error(`Error: ${err.message}`);
    console.error(`Stack: ${err.stack}`);

    // Prevent stack trace exposure
    const errorResponse = {
        error: 'Internal Server Error',
        message: 'An unexpected error occurred'
    };

    // Provide more details for validation errors
    if (err.name === 'ValidationError') {
        return res.status(400).json({
            error: 'Validation Error',
            message: err.message
        });
    }

    res.status(500).json(errorResponse);
};

// 5. NOT FOUND HANDLER
const notFoundHandler = (req, res, next) => {
    res.status(404).json({
        error: 'Not Found',
        message: `Route ${req.method} ${req.url} not found`
    });
};

// ====================
// ENHANCED ROUTES WITH VALIDATION
// ====================

// Health endpoint with input validation
app.get('/health', (req, res) => {
    try {
        const healthData = {
            status: 'ok',
            timestamp: new Date().toISOString(),
            uptime: process.uptime()
        };

        // Add optional details if requested
        if (req.query.detailed === 'true') {
            healthData.details = {
                nodeVersion: process.version,
                memory: process.memoryUsage()
            };
        }

        res.json(healthData);
    } catch (error) {
        next(error);
    }
});

// Users endpoint with proper validation
app.get('/users', validateQueryParams, (req, res, next) => {
    try {
        // Extract and validate parameters
        const limit = req.query.limit ? parseInt(req.query.limit, 10) : 10;
        const offset = req.query.offset ? parseInt(req.query.offset, 10) : 0;

        // Validate ranges
        if (limit < 1 || limit > 100) {
            return res.status(400).json({
                error: 'Invalid parameter',
                message: 'Limit must be between 1 and 100'
            });
        }

        if (offset < 0) {
            return res.status(400).json({
                error: 'Invalid parameter', 
                message: 'Offset must be non-negative'
            });
        }

        // Mock data (in real app, this would come from database)
        const allUsers = [
            { id: 1, name: 'Alice', email: 'alice@example.com' },
            { id: 2, name: 'Bob', email: 'bob@example.com' },
            { id: 3, name: 'Charlie', email: 'charlie@example.com' }
        ];

        // Apply pagination
        const users = allUsers.slice(offset, offset + limit);

        res.json({
            data: users,
            meta: {
                total: allUsers.length,
                limit,
                offset,
                hasMore: offset + limit < allUsers.length
            }
        });

    } catch (error) {
        next(error);
    }
});

// New endpoint demonstrating POST validation
app.post('/users', (req, res, next) => {
    try {
        const { name, email } = req.body;

        // Input validation
        const errors = [];

        if (!name || typeof name !== 'string' || name.trim().length < 2) {
            errors.push('Name is required and must be at least 2 characters');
        }

        if (!email || typeof email !== 'string') {
            errors.push('Email is required');
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
            errors.push('Invalid email format');
        }

        if (errors.length > 0) {
            return res.status(400).json({
                error: 'Validation Error',
                messages: errors
            });
        }

        // Sanitize inputs
        const sanitizedName = name.trim();
        const sanitizedEmail = email.trim().toLowerCase();

        // Business logic would go here (save to database, etc.)
        const newUser = {
            id: Date.now(), // Mock ID generation
            name: sanitizedName,
            email: sanitizedEmail,
            createdAt: new Date().toISOString()
        };

        res.status(201).json({
            message: 'User created successfully',
            user: newUser
        });

    } catch (error) {
        next(error);
    }
});

// ====================
// ERROR HANDLING SETUP
// ====================

// Apply error handlers
app.use(notFoundHandler);
app.use(errorHandler);

// ====================
// SERVER STARTUP WITH ERROR HANDLING
// ====================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
    console.log('SIGTERM received: closing server...');
    server.close(() => {
        console.log('Server closed');
        process.exit(0);
    });
});

process.on('SIGINT', () => {
    console.log('SIGINT received: closing server...');
    server.close(() => {
        console.log('Server closed');
        process.exit(0);
    });
});

// Unhandled error handling
process.on('uncaughtException', (error) => {
    console.error('Uncaught Exception:', error);
    server.close(() => process.exit(1));
});

process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

module.exports = app;

