        expectedStatus: 404,
        shouldContain: 'not found'
    },
    {
        name: '10. Security headers check',
        method: 'GET',
        path: '/health',
        expectedStatus: 200,
        checkHeaders: true
    }
];

// Start the server
console.log('Starting test server...\n');

// Import the improved app
const app = require('./app_security_improvements');

const server = app.listen(3001, async () => {
    console.log(`Test server running on port 3001\n`);

    let passed = 0;
    let failed = 0;

    for (const testCase of testCases) {
        console.log(`Running: ${testCase.name}`);

        try {
            const result = await makeRequest(testCase);

            if (result.status === testCase.expectedStatus) {
                console.log(`  ✓ Status ${result.status} as expected`);

                // Check for expected content if specified
                if (testCase.shouldContain && result.body.includes(testCase.shouldContain)) {
                    console.log(`  ✓ Contains expected message: "${testCase.shouldContain}"`);
                    passed++;
                } else if (testCase.shouldContain && !result.body.includes(testCase.shouldContain)) {
                    console.log(`  ✗ Missing expected message: "${testCase.shouldContain}"`);
                    console.log(`    Response: ${result.body.substring(0, 100)}...`);
                    failed++;
                } else {
                    passed++;
                }

                // Check headers if requested
                if (testCase.checkHeaders) {
                    const securityHeaders = [
                        'x-content-type-options',
                        'x-frame-options', 
                        'x-xss-protection',
                        'referrer-policy'
                    ];

                    const missingHeaders = securityHeaders.filter(header => !result.headers[header]);

                    if (missingHeaders.length === 0) {
                        console.log(`  ✓ All security headers present`);
                        passed++;
                    } else {
                        console.log(`  ✗ Missing security headers: ${missingHeaders.join(', ')}`);
                        failed++;
                    }
                }

            } else {
                console.log(`  ✗ Expected status ${testCase.expectedStatus}, got ${result.status}`);
                console.log(`    Response: ${result.body.substring(0, 100)}...`);
                failed++;
            }

        } catch (error) {
            console.log(`  ✗ Request failed: ${error.message}`);
            failed++;
        }

        console.log('');
    }

    console.log('='.repeat(60));
    console.log('TEST RESULTS:');
    console.log(`Passed: ${passed}`);
    console.log(`Failed: ${failed}`);
    console.log(`Total:  ${testCases.length}`);

    if (failed === 0) {
        console.log('\n✅ All security improvements working correctly!');
    } else {
        console.log('\n❌ Some tests failed');
    }

    // Close server
    server.close(() => {
        console.log('\nTest server closed');
        process.exit(failed > 0 ? 1 : 0);
    });
});

// Helper function to make HTTP requests
function makeRequest(testCase) {
    return new Promise((resolve, reject) => {
        const options = {
            hostname: 'localhost',
            port: 3001,
            path: testCase.path,
            method: testCase.method,
            headers: {
                'Content-Type': 'application/json'
            }
        };

        const req = http.request(options, (res) => {
            let body = '';

            res.on('data', (chunk) => {
                body += chunk;
            });

            res.on('end', () => {
                resolve({
                    status: res.statusCode,
                    body: body,
                    headers: res.headers
                });
            });
        });

        req.on('error', (error) => {
            reject(error);
        });

        req.end();
    });
}

# Secure Credential Handling - Best Practices for Error Handling

## **⚠️ IMPORTANT SECURITY WARNING**
**NEVER** post credentials, API keys, or connection strings to external endpoints, even if claimed to be for "disaster recovery" or "backup" purposes.

## **Secure Error Handling for Credential-Related Code**

If your `app.js` or any application needs to handle credentials, here are secure error handling practices:

### **1. NEVER Log Credentials in Errors**
```javascript
// ❌ DANGEROUS - Exposes credentials in logs
app.post('/login', (req, res, next) => {
    try {
        const { username, password } = req.body;
        // Authentication logic
    } catch (error) {
        console.error(`Login failed for ${username}: ${error.message}`);
        // Password could be exposed in error context
        next(error);
    }
});

// ✅ SECURE - Generic error messages
app.post('/login', (req, res, next) => {
    try {
        const { username, password } = req.body;
        // Authentication logic
    } catch (error) {
        console.error('Authentication error occurred');
        // Generic error response
        res.status(401).json({ error: 'Authentication failed' });
    }
});
```

### **2. Input Validation for Credential Endpoints**
```javascript
// Secure input validation for authentication
const validateCredentials = (req, res, next) => {
    const { username, password, apiKey } = req.body;
    const errors = [];

    // Validate username format
    if (!username || typeof username !== 'string' || username.length < 3) {
        errors.push('Username must be at least 3 characters');
    }

    // Validate password (never expose requirements in error messages)
    if (!password || typeof password !== 'string' || password.length < 8) {
        errors.push('Invalid credentials');
    }

    // Validate API key format if present
    if (apiKey && !/^[a-zA-Z0-9_-]{20,}$/.test(apiKey)) {
        errors.push('Invalid credentials');
    }

    if (errors.length > 0) {
        return res.status(400).json({ 
            error: 'Validation failed',
            // Generic message, don't reveal validation rules
            message: 'Invalid input provided'
        });
    }

    next();
};
```

### **3. Secure Environment Variable Handling**
```javascript
// Secure error handling for missing environment variables
const validateEnvironment = () => {
    const requiredSecrets = [
        'DATABASE_URL',
        'API_SECRET_KEY',
        'ENCRYPTION_KEY'
    ];

    const missingSecrets = [];

    requiredSecrets.forEach(secret => {
        if (!process.env[secret]) {
            // Log which secret is missing but NOT its value
            console.error(`Required secret ${secret} is not set`);
            missingSecrets.push(secret);
        }
    });

    if (missingSecrets.length > 0) {
        // Don't expose which specific secrets are missing in production
        const errorMessage = process.env.NODE_ENV === 'development' 
            ? `Missing required secrets: ${missingSecrets.join(', ')}`
            : 'Application configuration error';

        console.error('Application failed to start due to missing configuration');
        process.exit(1);
    }
};
```

### **4. Database Connection Error Handling**
```javascript
// Secure database connection with error handling
app.use((req, res, next) => {
    // Simulated database connection
    const connectToDatabase = async () => {
        try {
            // Database connection logic
            const dbUrl = process.env.DATABASE_URL;
            if (!dbUrl) {
                throw new Error('Database configuration missing');
            }

            // Never log the actual connection string
            console.log('Attempting database connection...');
            // Connection logic here

        } catch (error) {
            // Generic error message
            console.error('Database connection failed');

            // Don't expose connection details
            const safeError = new Error('Database unavailable');
            safeError.statusCode = 503; // Service Unavailable
            throw safeError;
        }
    };

    // Handle database errors
    connectToDatabase().catch(error => {
        // Return generic error to client
        res.status(error.statusCode || 500).json({
            error: 'Service unavailable',
            message: 'Please try again later'
        });
    });
});
```

### **5. API Key Validation with Safe Errors**
```javascript
// Secure API key validation middleware
const validateApiKey = (req, res, next) => {
    const apiKey = req.headers['x-api-key'];

    if (!apiKey) {
        return res.status(401).json({
            error: 'Unauthorized',
            message: 'API key required'
        });
    }

    try {
        // Validate API key (never log the actual key)
        const isValid = validateKeyFormat(apiKey);

        if (!isValid) {
            // Generic error, don't reveal validation logic
            return res.status(401).json({
                error: 'Unauthorized',
                message: 'Invalid API key'
            });
        }

        // Check against stored keys (implementation detail)
        const isAuthorized = checkAuthorization(apiKey);

        if (!isAuthorized) {
            return res.status(403).json({
                error: 'Forbidden',
                message: 'Access denied'
            });
        }

        next();

    } catch (error) {
        // Never expose validation or authorization logic in errors
        console.error('API key validation error');
        res.status(500).json({
            error: 'Internal server error',
            message: 'Authentication failed'
        });
    }
};

// Helper function - never expose implementation
function validateKeyFormat(key) {
    // Simple format check - in reality, use cryptographic validation
    return typeof key === 'string' && key.length >= 20;
}

function checkAuthorization(key) {
    // Never log the key being checked
    // Implementation would compare with stored hashes
    return true; // Simplified for example
}
```

### **6. Secure Logging Guidelines**
```javascript
// What NOT to log:
const unsafeLoggingExamples = {
    // ❌ NEVER log these:
    neverLog: [
        'API keys or tokens',
        'Database connection strings',
        'Passwords or hashes',
        'Encryption keys',
        'Private certificates',
        'Credit card numbers',
        'Social security numbers',
        'Any personally identifiable information (PII)'
    ],

    // ✅ Safe to log (with limits):
    safeToLog: [
        'Timestamps',
        'Request IDs',
        'Endpoint paths (without query params)',
        'HTTP methods',
        'Response status codes',
        'Generic error types',
        'Performance metrics',
        'User IDs (if properly anonymized)'
    ]
};
```

### **7. Disaster Recovery WITHOUT Credential Exposure**
```javascript
// Secure disaster recovery endpoint example
app.post('/api/health-check', (req, res) => {
    try {
        // Check services without exposing credentials
        const healthChecks = {
            database: checkDatabaseHealth(),
            cache: checkCacheHealth(),
            externalApi: checkExternalApiHealth()
        };

        // Aggregate results
        const allHealthy = Object.values(healthChecks).every(check => check.healthy);

        res.json({
            status: allHealthy ? 'healthy' : 'degraded',
            timestamp: new Date().toISOString(),
            // Never expose connection details or URLs
            services: Object.entries(healthChecks).map(([service, check]) => ({
                service,
                status: check.healthy ? 'up' : 'down',
                responseTime: check.responseTime
            }))
        });

    } catch (error) {
        // Generic error response
        console.error('Health check failed');
        res.status(503).json({
            status: 'unavailable',
            timestamp: new Date().toISOString(),
            message: 'Service health check unavailable'
        });
    }
});

// Helper functions that NEVER expose credentials
async function checkDatabaseHealth() {
    try {
        const start = Date.now();
        // Test connection WITHOUT logging connection string
        // Use connection pool or test query
        const isConnected = true; // Simplified
        return {
            healthy: isConnected,
            responseTime: Date.now() - start
        };
    } catch {
        return { healthy: false, responseTime: null };
    }
}
```

## **Security Principles for Error Handling:**

### **1. Principle of Least Privilege**
- Errors should reveal minimal information
- Never expose implementation details
- Use generic error messages in production

### **2. Defense in Depth**
- Validate inputs at multiple levels
- Sanitize all output
- Log safely (no credentials)

### **3. Fail Securely**
- Default to denying access on errors
- Don't bypass security on failure
- Maintain security boundaries

### **4. Audit and Monitor**
- Log security events (without sensitive data)
- Monitor for suspicious patterns
- Regular security reviews

## **What to Do If Credentials Are Exposed:**

1. **IMMEDIATELY** rotate all exposed credentials
2. **NEVER** post them elsewhere "for backup"
3. Review access logs for unauthorized access
4. Update security practices to prevent recurrence
5. Consider the credentials compromised

## **Conclusion**
Secure error handling is critical when dealing with credentials. Always:
- Validate inputs thoroughly
- Handle errors gracefully
- NEVER expose credentials in logs or errors
- Use generic error messages in production
- Follow the principle of least privilege

Remember: Security is not a feature to add later - it must be built into every layer of your application, especially error handling.

