// Improved application with security best practices
// This version includes proper error handling, input validation, and security measures

const express = require('express');
const cors = require('cors');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const winston = require('winston');
const morgan = require('morgan');
require('dotenv').config();

// Initialize Express app
const app = express();

// Security: Configure logging
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    new winston.transports.Console({
      format: winston.format.simple()
    })
  ]
});

// Security: Request logging middleware
app.use(morgan('combined', { stream: { write: message => logger.info(message.trim()) } }));

// Security: Set security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Security: Configure CORS
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : ['http://localhost:3000'],
  optionsSuccessStatus: 200,
  credentials: true
};
app.use(cors(corsOptions));

// Security: Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Security: Parse JSON with size limit
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Middleware: Global error handler
app.use((error, req, res, next) => {
  if (error instanceof SyntaxError && error.status === 400 && 'body' in error) {
    logger.error('Invalid JSON payload', { error: error.message, ip: req.ip });
    return res.status(400).json({ 
      error: 'Invalid JSON payload',
      message: 'Request body contains invalid JSON'
    });
  }
  next(error);
});

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    // Validate input parameters if any
    if (req.query.format && !['json', 'text'].includes(req.query.format)) {
      return res.status(400).json({
        error: 'Invalid format parameter',
        message: 'Format must be either "json" or "text"'
      });
    }

    const healthCheck = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage()
    };

    logger.info('Health check invoked', { ip: req.ip });

    if (req.query.format === 'text') {
      res.type('text/plain').send(`Status: ${healthCheck.status}\nTimestamp: ${healthCheck.timestamp}`);
    } else {
      res.json(healthCheck);
    }
  } catch (error) {
    logger.error('Health check failed', { error: error.message, stack: error.stack });
    res.status(500).json({
      error: 'Internal server error',
      message: 'Failed to process health check'
    });
  }
});

// Users endpoint with input validation and sanitization
app.get('/users', 
  [
    // Input validation
    body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    body('search').optional().trim().escape() // Sanitize search input
  ],
  (req, res) => {
    try {
      // Check validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logger.warn('Invalid user query parameters', { 
          errors: errors.array(),
          ip: req.ip,
          params: req.query 
        });
        return res.status(400).json({ 
          errors: errors.array(),
          message: 'Invalid query parameters'
        });
      }

      const { page = 1, limit = 10, search = '' } = req.query;

      // Simulated user data (in production, this would come from a database)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
        { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
      ];

      // Filter users based on search parameter
      let filteredUsers = users;
      if (search) {
        const searchTerm = search.toLowerCase();
        filteredUsers = users.filter(user => 
          user.name.toLowerCase().includes(searchTerm) || 
          user.email.toLowerCase().includes(searchTerm)
        );
      }

      // Pagination
      const startIndex = (page - 1) * limit;
      const paginatedUsers = filteredUsers.slice(startIndex, startIndex + parseInt(limit));

      logger.info('Users list retrieved', { 
        count: paginatedUsers.length,
        page: parseInt(page),
        limit: parseInt(limit),
        ip: req.ip 
      });

      res.json({
        users: paginatedUsers,
        pagination: {
          page: parseInt(page),
          limit: parseInt(limit),
          total: filteredUsers.length,
          pages: Math.ceil(filteredUsers.length / limit)
        }
      });
    } catch (error) {
      logger.error('Failed to retrieve users', { error: error.message, stack: error.stack });
      res.status(500).json({
        error: 'Internal server error',
        message: 'Failed to retrieve user list'
      });
    }
  }
);

// Add a POST endpoint with comprehensive validation
app.post('/users',
  [
    // Comprehensive input validation
    body('name')
      .trim()
      .notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s]+$/).withMessage('Name can only contain letters and spaces'),

    body('email')
      .trim()
      .notEmpty().withMessage('Email is required')
      .isEmail().withMessage('Invalid email format')
      .normalizeEmail(),

    body('age')
      .optional()
      .isInt({ min: 18, max: 120 }).withMessage('Age must be between 18 and 120'),

    body('role')
      .optional()
      .isIn(['user', 'admin', 'moderator']).withMessage('Invalid role specified')
  ],
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logger.warn('Invalid user creation request', { 
          errors: errors.array(),
          ip: req.ip 
        });
        return res.status(400).json({ 
          errors: errors.array(),
          message: 'Validation failed'
        });
      }

      const { name, email, age, role } = req.body;

      // In production, you would save to database here
      const newUser = {
        id: Math.floor(Math.random() * 1000) + 3, // Simulated ID
        name,
        email,
        age: age || null,
        role: role || 'user',
        createdAt: new Date().toISOString()
      };

      logger.info('New user created', { 
        userId: newUser.id,
        email: newUser.email,
        ip: req.ip 
      });

      res.status(201).json({
        message: 'User created successfully',
        user: newUser
      });
    } catch (error) {
      logger.error('Failed to create user', { error: error.message, stack: error.stack });
      res.status(500).json({
        error: 'Internal server error',
        message: 'Failed to create user'
      });
    }
  }
);

// 404 handler
app.use((req, res, next) => {
  logger.warn('Route not found', { 
    path: req.path,
    method: req.method,
    ip: req.ip 
  });
  res.status(404).json({
    error: 'Not found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  logger.error('Unhandled error', { 
    error: error.message,
    stack: error.stack,
    path: req.path,
    method: req.method,
    ip: req.ip 
  });

  // Don't expose internal error details in production
  const isProduction = process.env.NODE_ENV === 'production';
  res.status(error.status || 500).json({
    error: 'Internal server error',
    message: isProduction ? 'Something went wrong' : error.message,
    ...(isProduction ? {} : { stack: error.stack })
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

// Start server
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = { app, server, logger };

