// Improved application with security best practices
// This version includes comprehensive error handling and input validation

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers

// CORS configuration - restrict to trusted origins in production
const corsOptions = {
  origin: process.env.NODE_ENV === 'production' 
    ? [process.env.ALLOWED_ORIGIN || 'http://localhost:3000'] 
    : '*',
  optionsSuccessStatus: 200
};
app.use(cors(corsOptions));

// Request parsing with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Rate limiting - prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.',
  skipSuccessfulRequests: false,
  skipFailedRequests: false,
});
app.use(limiter);

// Input validation middleware
const validateQueryParams = (req, res, next) => {
  // Add parameter validation logic here
  const { page, limit, sort } = req.query;

  // Validate numeric parameters
  if (page && !/^\d+$/.test(page)) {
    return res.status(400).json({ error: 'Page must be a positive integer' });
  }

  if (limit && (!/^\d+$/.test(limit) || parseInt(limit) > 100)) {
    return res.status(400).json({ 
      error: 'Limit must be a positive integer and cannot exceed 100' 
    });
  }

  // Validate sort parameter
  if (sort && !/^[a-zA-Z0-9_,-]+$/.test(sort)) {
    return res.status(400).json({ 
      error: 'Invalid sort parameter format' 
    });
  }

  next();
};

// Health check endpoint with enhanced info
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      env: process.env.NODE_ENV || 'development',
      memory: process.memoryUsage()
    });
  } catch (error) {
    res.status(500).json({ 
      status: 'error', 
      timestamp: new Date().toISOString(),
      message: 'Health check failed'
    });
  }
});

// Users endpoint with input validation and pagination
app.get('/users', validateQueryParams, (req, res) => {
  try {
    const { page = 1, limit = 10 } = req.query;
    const pageNum = parseInt(page);
    const limitNum = parseInt(limit);

    // Mock data - in production this would come from a database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', createdAt: '2024-01-01' },
      { id: 2, name: 'Bob', email: 'bob@example.com', createdAt: '2024-01-02' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', createdAt: '2024-01-03' },
      { id: 4, name: 'Diana', email: 'diana@example.com', createdAt: '2024-01-04' },
      { id: 5, name: 'Eve', email: 'eve@example.com', createdAt: '2024-01-05' },
    ];

    // Calculate pagination
    const startIndex = (pageNum - 1) * limitNum;
    const endIndex = pageNum * limitNum;
    const paginatedUsers = allUsers.slice(startIndex, endIndex);

    // Sanitize response - remove sensitive data
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: user.name,
      createdAt: user.createdAt
    }));

    res.json({
      data: sanitizedUsers,
      pagination: {
        page: pageNum,
        limit: limitNum,
        totalItems: allUsers.length,
        totalPages: Math.ceil(allUsers.length / limitNum),
        hasNextPage: endIndex < allUsers.length,
        hasPrevPage: startIndex > 0
      }
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Failed to retrieve users',
      requestId: req.id || Date.now().toString(36)
    });
  }
});

// 404 handler - catch all undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`,
    timestamp: new Date().toISOString()
  });
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Default error response
  const errorResponse = {
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' 
      ? 'An unexpected error occurred' 
      : err.message || 'An unexpected error occurred',
    timestamp: new Date().toISOString(),
    requestId: req.id || Date.now().toString(36)
  };

  // Add stack trace in development
  if (process.env.NODE_ENV !== 'production') {
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// Environment validation
const validateEnvironment = () => {
  const requiredVars = [];

  if (process.env.NODE_ENV === 'production') {
    requiredVars.push('DATABASE_URL', 'JWT_SECRET');
  }

  const missingVars = requiredVars.filter(varName => !process.env[varName]);

  if (missingVars.length > 0) {
    throw new Error(`Missing required environment variables: ${missingVars.join(', ')}`);
  }
};

// Graceful shutdown handling
const gracefulShutdown = (signal) => {
  console.log(`Received ${signal}. Starting graceful shutdown...`);

  // Close server and clean up resources
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
};

// Start server with port from environment or default
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);

  try {
    validateEnvironment();
    console.log('Environment validation passed');
  } catch (error) {
    console.error('Environment validation failed:', error.message);
    if (process.env.NODE_ENV === 'production') {
      console.error('Critical error: Shutting down due to missing required environment variables');
      gracefulShutdown('ENV_VALIDATION_FAILED');
    }
  }
});

// Handle graceful shutdown signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions and rejections
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  gracefulShutdown('UNCAUGHT_EXCEPTION');
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown('UNHANDLED_REJECTION');
});

module.exports = { app, server };

