// Minimal secure Express app with essential security improvements
// Focuses on critical security practices that should be in every Express app

const express = require('express');
const helmet = require('helmet');
const app = express();

// ========== CRITICAL SECURITY IMPROVEMENTS ==========

// 1. Security headers - prevents XSS, clickjacking, etc.
app.use(helmet());

// 2. Request size limiting - prevents DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 3. Input validation middleware
const validateInput = (req, res, next) => {
  // Validate numeric parameters
  if (req.query.id && !/^\d+$/.test(req.query.id)) {
    return res.status(400).json({ 
      error: 'ID must be a positive integer' 
    });
  }

  // Validate string parameters (prevent injection)
  if (req.query.search && !/^[a-zA-Z0-9\s\-_]+$/.test(req.query.search)) {
    return res.status(400).json({ 
      error: 'Invalid search parameter' 
    });
  }

  next();
};

// 4. Structured error handling
const handleErrors = (err, req, res, next) => {
  console.error('Error:', err.message, err.stack);

  if (err.type === 'validation') {
    return res.status(400).json({ 
      error: 'Validation Error', 
      message: err.message 
    });
  }

  // Don't expose internal error details in production
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(err.status || 500).json({ 
    error: 'Internal Server Error', 
    message: message,
    timestamp: new Date().toISOString()
  });
};

// ========== APPLICATION ENDPOINTS ==========

app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString() 
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Health check failed' 
    });
  }
});

app.get('/users', validateInput, (req, res) => {
  try {
    // Example: Validate and sanitize inputs
    const { id, search } = req.query;

    // Mock data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter by ID if provided
    let filteredUsers = users;
    if (id) {
      filteredUsers = users.filter(user => user.id === parseInt(id));
    }

    // Search if provided
    if (search) {
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(search.toLowerCase())
      );
    }

    // Sanitize response - don't expose email unless necessary
    const sanitizedUsers = filteredUsers.map(user => ({
      id: user.id,
      name: user.name
    }));

    res.json(sanitizedUsers);

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Failed to retrieve users',
      message: 'An internal error occurred'
    });
  }
});

// 5. Rate limiting simulation (basic version without external package)
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const RATE_LIMIT_MAX = 100;

app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  if (!requestCounts.has(ip)) {
    requestCounts.set(ip, { count: 1, startTime: now });
  } else {
    const record = requestCounts.get(ip);

    // Reset if window has passed
    if (now - record.startTime > RATE_LIMIT_WINDOW) {
      record.count = 1;
      record.startTime = now;
    } else if (record.count >= RATE_LIMIT_MAX) {
      return res.status(429).json({ 
        error: 'Too Many Requests',
        message: 'Rate limit exceeded. Please try again later.',
        retryAfter: Math.ceil((record.startTime + RATE_LIMIT_WINDOW - now) / 1000)
      });
    } else {
      record.count++;
    }
  }

  next();
});

// 6. 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found', 
    message: `${req.method} ${req.path} is not available` 
  });
});

// 7. Global error handler (must be last)
app.use(handleErrors);

// 8. Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received: starting graceful shutdown');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received: shutting down');
  server.close(() => {
    process.exit(0);
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);

  // Validate critical environment variables
  if (process.env.NODE_ENV === 'production' && !process.env.JWT_SECRET) {
    console.error('CRITICAL: JWT_SECRET not set in production');
    process.exit(1);
  }
});

module.exports = app;

# Security Improvements for app.js

## Critical Security Issues in Current Code

### 1. Missing Input Validation
**Risk:** Injection attacks, data corruption
**Solution:** Validate all user inputs before processing
```javascript
// Bad: No validation
app.get('/users', (req, res) => {
  const id = req.query.id; // Unsafe - could be malicious
});

// Good: Validate input
app.get('/users', validateInput, (req, res) => {
  const id = req.query.id; // Validated before reaching handler
});

const validateInput = (req, res, next) => {
  if (req.query.id && !/^\d+$/.test(req.query.id)) {
    return res.status(400).json({ error: 'Invalid ID format' });
  }
  next();
};
```

### 2. Missing Error Handling
**Risk:** Server crashes, information disclosure
**Solution:** Global error handler + try-catch blocks
```javascript
// Global error handler (must be last middleware)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose stack traces in production
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(err.status || 500).json({ 
    error: 'Internal Server Error', 
    message: message,
    timestamp: new Date().toISOString()
  });
});

// Individual endpoint error handling
app.get('/users', async (req, res) => {
  try {
    const users = await getUserData();
    res.json(users);
  } catch (error) {
    console.error('Error in /users:', error);
    res.status(500).json({ error: 'Failed to get users' });
  }
});
```

### 3. Missing Security Headers
**Risk:** XSS attacks, clickjacking, MIME sniffing
**Solution:** Use Helmet.js
```javascript
const helmet = require('helmet');
app.use(helmet()); // Sets Content-Security-Policy, X-Frame-Options, etc.
```

### 4. No Rate Limiting
**Risk:** DoS attacks, brute force attacks
**Solution:** Implement rate limiting
```javascript
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests
  message: 'Too many requests'
});
app.use(limiter);
```

### 5. No Request Size Limiting
**Risk:** Memory exhaustion attacks
**Solution:** Limit request body size
```javascript
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
```

## Recommended Implementation Priority

### Immediate (Critical) Improvements:
1. **Add Helmet.js** - Security headers
2. **Add input validation** - All user inputs
3. **Add global error handler** - Prevent unhandled exceptions
4. **Add request size limits** - Prevent DoS attacks
5. **Add CORS configuration** - Restrict origins in production

### Short-term Improvements:
1. **Add rate limiting** - Prevent brute force attacks
2. **Add request logging** - For debugging and security monitoring
3. **Add environment validation** - Check required variables
4. **Add graceful shutdown** - Clean up resources

### Long-term Improvements:
1. **Add authentication/authorization** - If needed
2. **Add audit logging** - For security compliance
3. **Add request ID tracking** - For tracing requests
4. **Add health checks** - For monitoring

## Quick Wins for Current Code

Here are minimal changes to improve the existing code:

```javascript
const express = require('express');
const app = express();

// 1. Add security headers manually (if can't install Helmet)
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  next();
});

// 2. Add request size limits
app.use(express.json({ limit: '10kb' }));

// 3. Add global error handler
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ 
    error: 'Internal Server Error',
    timestamp: new Date().toISOString()
  });
});

// 4. Add input validation to existing endpoints
app.get('/users', (req, res) => {
  // Validate any query parameters
  const { page, limit } = req.query;

  if (page && !/^\d+$/.test(page)) {
    return res.status(400).json({ error: 'Page must be a number' });
  }

  if (limit && (!/^\d+$/.test(limit) || parseInt(limit) > 100)) {
    return res.status(400).json({ error: 'Limit must be ≤ 100' });
  }

  // Existing code...
  res.json([{ id: 1, name: 'Alice' }, { id: 2, name: 'Bob' }]);
});

// 5. Add 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: `${req.method} ${req.path} not found`
  });
});
```

## Dependencies Required

Add to package.json:
```json
{
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.0.0",
    "express-rate-limit": "^7.1.5",
    "cors": "^2.8.5"
  }
}
```

## Testing Security Improvements

Test your improvements with:
1. **Input validation**: Send malformed data to endpoints
2. **Error handling**: Force errors in endpoints
3. **Rate limiting**: Send many requests quickly
4. **Security headers**: Use browser dev tools to check headers

## Monitoring and Maintenance

1. **Log security events**: Log failed auth attempts, rate limit hits
2. **Regular dependency updates**: Keep security packages updated
3. **Security headers check**: Regularly audit headers
4. **Error monitoring**: Use tools to track application errors

// Minimal improvements to existing app.js
// Adds critical security and error handling with minimal changes

const express = require('express');
const app = express();

