    // Validate specific parameters
    const { limit } = req.query;

    // Additional validation
    if (limit && parseInt(limit) > 50) {
      return res.status(400).json({ 
        error: 'Bad Request', 
        message: 'Limit cannot exceed 50' 
      });
    }

    // Sanitize response data (example)
