// Improved application with security best practices
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const compression = require('compression');
const morgan = require('morgan');
const { body, validationResult } = require('express-validator');

const app = express();

// Security Middleware Configuration

// 1. HTTP Security Headers using Helmet
app.use(helmet({
    contentSecurityPolicy: {
        directives: {
            defaultSrc: ["'self'"],
            styleSrc: ["'self'", "'unsafe-inline'"],
            scriptSrc: ["'self'"],
            imgSrc: ["'self'", "data:"],
        },
    },
    hsts: {
        maxAge: 31536000, // 1 year
        includeSubDomains: true,
        preload: true
    }
}));

// 2. CORS Configuration
const corsOptions = {
    origin: process.env.NODE_ENV === 'production' 
        ? ['https://yourdomain.com'] 
        : ['http://localhost:3000'],
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true,
    maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 3. Rate Limiting
const apiLimiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100, // limit each IP to 100 requests per windowMs
    message: 'Too many requests from this IP, please try again later.',
    standardHeaders: true,
    legacyHeaders: false,
});
app.use('/api/', apiLimiter);

// 4. Compression for better performance
app.use(compression());

// 5. Request parsing with size limits
app.use(express.json({
    limit: '10kb', // Limit request body size
    strict: true   // Only accept arrays and objects
}));
app.use(express.urlencoded({
    extended: true,
    limit: '10kb'
}));

// 6. Structured logging
app.use(morgan('combined')); // Use 'dev' for development, 'combined' for production

// Global Error Handling Middleware
app.use((err, req, res, next) => {
    console.error('Unhandled error:', {
        error: err.message,
        stack: process.env.NODE_ENV === 'production' ? undefined : err.stack,
        timestamp: new Date().toISOString(),
        path: req.path,
        method: req.method,
        ip: req.ip
    });

    // Don't leak error details in production
    const errorResponse = process.env.NODE_ENV === 'production' 
        ? { error: 'Internal Server Error' }
        : { error: err.message, stack: err.stack };

    res.status(err.status || 500).json(errorResponse);
});

// 404 Handler
app.use((req, res) => {
    res.status(404).json({
        error: 'Not Found',
        message: `Cannot ${req.method} ${req.path}`
    });
});

// Health endpoint with input validation
app.get('/health', 
    // Input validation middleware
    [
        body('timestamp').optional().isISO8601().toDate(),
        body('detailed').optional().isBoolean().toBoolean()
    ],
    (req, res) => {
        try {
            // Check for validation errors
            const errors = validationResult(req);
            if (!errors.isEmpty()) {
                return res.status(400).json({
                    error: 'Bad Request',
                    details: errors.array()
                });
            }

            const healthData = {
                status: 'ok',
                timestamp: new Date().toISOString(),
                uptime: process.uptime(),
                memoryUsage: process.memoryUsage(),
                nodeVersion: process.version
            };

            // Only include environment details if explicitly requested and not in production
            if (req.query.detailed === 'true' && process.env.NODE_ENV !== 'production') {
                healthData.environment = process.env.NODE_ENV;
            }

            // Security: Remove potentially sensitive information
            const sanitizedData = { ...healthData };
            delete sanitizedData.memoryUsage?.heapUsed; // Don't expose heap details

            res.json(sanitizedData);
        } catch (error) {
            // Log and handle unexpected errors
            console.error('Health check error:', error);
            res.status(500).json({ 
                status: 'error', 
                timestamp: new Date().toISOString(),
                message: 'Health check failed'
            });
        }
    }
);

// Users endpoint with input validation and sanitization
app.get('/users', 
    [
        body('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
        body('offset').optional().isInt({ min: 0 }).toInt(),
        body('search').optional().trim().escape() // Sanitize search input
    ],
    async (req, res, next) => {
        try {
            // Check for validation errors
            const errors = validationResult(req);
            if (!errors.isEmpty()) {
                return res.status(400).json({
                    error: 'Bad Request',
                    details: errors.array()
                });
            }

            const { limit = 10, offset = 0, search } = req.query;

            // Security: Validate and sanitize inputs
            const validatedLimit = Math.min(parseInt(limit), 100); // Max 100 records
            const validatedOffset = Math.max(0, parseInt(offset));

            // Mock database query with parameterization (in real app, use prepared statements)
            const users = [
                { 
                    id: 1, 
                    name: 'Alice', 
                    email: 'alice@example.com',
                    created_at: new Date().toISOString()
                },
                { 
                    id: 2, 
                    name: 'Bob', 
                    email: 'bob@example.com',
                    created_at: new Date().toISOString()
                },
            ];

            // Apply search filter if provided (with sanitized input)
            let filteredUsers = users;
            if (search) {
                const sanitizedSearch = req.query.search.toLowerCase();
                filteredUsers = users.filter(user => 
                    user.name.toLowerCase().includes(sanitizedSearch) ||
                    user.email.toLowerCase().includes(sanitizedSearch)
                );
            }

            // Apply pagination
            const paginatedUsers = filteredUsers.slice(
                validatedOffset, 
                validatedOffset + validatedLimit
            );

            // Set security headers for this response
            res.set({
                'X-Content-Type-Options': 'nosniff',
                'X-Frame-Options': 'DENY',
                'Referrer-Policy': 'strict-origin-when-cross-origin'
            });

            res.json({
                data: paginatedUsers,
                pagination: {
                    total: filteredUsers.length,
                    limit: validatedLimit,
                    offset: validatedOffset,
                    hasMore: (validatedOffset + validatedLimit) < filteredUsers.length
                },
                meta: {
                    timestamp: new Date().toISOString()
                }
            });

        } catch (error) {
            // Pass error to global error handler
            next(error);
        }
    }
);

// Add a secure POST endpoint example
app.post('/users',
    [
        body('name').trim().escape().isLength({ min: 1, max: 100 }),
        body('email').trim().normalizeEmail().isEmail(),
        body('age').optional().isInt({ min: 0, max: 150 }).toInt()
    ],
    async (req, res) => {
        try {
            const errors = validationResult(req);
            if (!errors.isEmpty()) {
                return res.status(400).json({
                    error: 'Bad Request',
                    details: errors.array()
                });
            }

            // In a real application, you would:
            // 1. Hash passwords with bcrypt
            // 2. Use database transactions
            // 3. Implement proper SQL injection protection

            const { name, email, age } = req.body;

            // Sanitize input before use
            const sanitizedName = name.trim();
            const sanitizedEmail = email.toLowerCase().trim();

            const newUser = {
                id: Date.now(), // In production, use proper ID generation
                name: sanitizedName,
                email: sanitizedEmail,
                age: age || null,
                created_at: new Date().toISOString()
            };

            // Security: Don't return full user object in response
            const safeResponse = {
                id: newUser.id,
                name: newUser.name,
                message: 'User created successfully'
            };

            res.status(201).json(safeResponse);

        } catch (error) {
            console.error('Create user error:', error);
            res.status(500).json({
                error: 'Internal Server Error',
                message: 'Failed to create user'
            });
        }
    }
);

// Environment-based configuration
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Graceful shutdown handling
const server = app.listen(PORT, HOST, () => {
    console.log(`Server running on http://${HOST}:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
    console.log('SIGTERM received. Starting graceful shutdown...');
    server.close(() => {
        console.log('HTTP server closed.');
        process.exit(0);
    });
});

process.on('SIGINT', () => {
    console.log('SIGINT received. Starting graceful shutdown...');
    server.close(() => {
        console.log('HTTP server closed.');
        process.exit(0);
    });
});

module.exports = { app, server };

