// Improved version of app.js with error handling and input validation
const express = require('express');
const app = express();

// Basic security headers
app.use((req, res, next) => {
    res.set({
        'X-Content-Type-Options': 'nosniff',
        'X-Frame-Options': 'DENY',
        'Strict-Transport-Security': 'max-age=31536000; includeSubDomains',
        'Content-Security-Policy': "default-src 'self'"
    });
    next();
});

// Request validation middleware
const validateRequest = (req, res, next) => {
    // Validate query parameters exist and are strings
    const queryParams = req.query;

    for (const [key, value] of Object.entries(queryParams)) {
        if (typeof value !== 'string') {
            return res.status(400).json({
                error: 'Bad Request',
                message: `Query parameter '${key}' must be a string`
            });
        }

        // Basic length validation
        if (value.length > 100) {
            return res.status(400).json({
                error: 'Bad Request',
                message: `Query parameter '${key}' exceeds maximum length of 100 characters`
            });
        }
    }
    next();
};

// Global error handler
app.use((err, req, res, next) => {
    console.error('Unhandled error:', {
        error: err.message,
        path: req.path,
        method: req.method,
        timestamp: new Date().toISOString()
    });

    res.status(500).json({
        error: 'Internal Server Error',
        message: 'An unexpected error occurred'
    });
});

// Health endpoint with validation
app.get('/health', validateRequest, (req, res, next) => {
    try {
        const healthData = {
            status: 'ok',
            timestamp: new Date().toISOString()
        };

        // Validate and sanitize optional parameters
        if (req.query.detailed) {
            if (req.query.detailed.toLowerCase() !== 'true') {
                return res.status(400).json({
                    error: 'Bad Request',
                    message: "Parameter 'detailed' must be 'true'"
                });
            }
            healthData.uptime = process.uptime();
        }

        res.json(healthData);
    } catch (error) {
        next(error);
    }
});

// Users endpoint with validation
app.get('/users', validateRequest, (req, res, next) => {
    try {
        const { limit, offset, search } = req.query;

        // Parse and validate limit
        let userLimit = 10; // default
        if (limit) {
            const parsedLimit = parseInt(limit, 10);
            if (isNaN(parsedLimit) || parsedLimit < 1 || parsedLimit > 100) {
                return res.status(400).json({
                    error: 'Bad Request',
                    message: "Parameter 'limit' must be an integer between 1 and 100"
                });
            }
            userLimit = parsedLimit;
        }

        // Parse and validate offset
        let userOffset = 0; // default
        if (offset) {
            const parsedOffset = parseInt(offset, 10);
            if (isNaN(parsedOffset) || parsedOffset < 0) {
                return res.status(400).json({
                    error: 'Bad Request',
                    message: "Parameter 'offset' must be a non-negative integer"
                });
            }
            userOffset = parsedOffset;
        }

        // Sanitize search input (basic XSS prevention)
        let sanitizedSearch = null;
        if (search) {
            sanitizedSearch = search.replace(/[<>]/g, ''); // Remove < and > characters
        }

        // Mock data
        const users = [
            { id: 1, name: 'Alice', email: 'alice@example.com' },
            { id: 2, name: 'Bob', email: 'bob@example.com' },
            { id: 3, name: 'Charlie', email: 'charlie@example.com' },
            { id: 4, name: 'Diana', email: 'diana@example.com' }
        ];

        // Apply search filter if provided
        let filteredUsers = users;
        if (sanitizedSearch) {
            const searchLower = sanitizedSearch.toLowerCase();
            filteredUsers = users.filter(user => 
                user.name.toLowerCase().includes(searchLower) ||
                user.email.toLowerCase().includes(searchLower)
            );
        }

        // Apply pagination
        const startIndex = Math.min(userOffset, filteredUsers.length);
        const endIndex = Math.min(startIndex + userLimit, filteredUsers.length);
        const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

        res.json({
            data: paginatedUsers,
            pagination: {
                total: filteredUsers.length,
                limit: userLimit,
                offset: userOffset,
                hasMore: endIndex < filteredUsers.length
            }
        });

    } catch (error) {
        next(error);
    }
});

// 404 handler
app.use((req, res) => {
    res.status(404).json({
        error: 'Not Found',
        message: `Cannot ${req.method} ${req.path}`
    });
});

// Use environment variable for port with fallback
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});

module.exports = app;

