// Enhanced application with comprehensive error handling and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const compression = require('compression');
const cors = require('cors');
const morgan = require('morgan');
require('dotenv').config();

const app = express();

// ========== SECURITY MIDDLEWARE ==========

// 1. Set security HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  }
}));

// 2. Enable CORS with secure configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : '*',
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With']
}));

// 3. Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all API routes
app.use('/api/', apiLimiter);

// 4. Request payload limits
app.use(express.json({ limit: '10kb' })); // Limit JSON payload to 10kb
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Compression for performance
app.use(compression());

// 6. HTTP request logging (avoid in production for sensitive data)
if (process.env.NODE_ENV !== 'production') {
  app.use(morgan('combined'));
}

// ========== VALIDATION MIDDLEWARE ==========

// Input validation middleware for common parameters
const validateUserId = (req, res, next) => {
  const { id } = req.params;

  if (id && !/^\d+$/.test(id)) {
    return res.status(400).json({
      error: 'Invalid user ID',
      message: 'User ID must be a positive integer'
    });
  }

  next();
};

const sanitizeInput = (req, res, next) => {
  // Remove any null byte injections
  if (req.body) {
    const sanitizedBody = {};
    for (const [key, value] of Object.entries(req.body)) {
      if (typeof value === 'string') {
        sanitizedBody[key] = value.replace(/\0/g, '');
      } else {
        sanitizedBody[key] = value;
      }
    }
    req.body = sanitizedBody;
  }
  next();
};

// ========== ERROR HANDLING MIDDLEWARE ==========

// 404 handler
app.use((req, res, next) => {
